WoWFQ[86652] = { t = "جا مانده در سایه‌ها", d = "loa سال‌های زیادی است با ما حرف نزده... از وقتی بچه بودم نه.\nو هیچ نشانه‌ای نشان نداده که حالا بخواهد به ما کمک کند.\nنه. دیگر فقط به خودمان هستیم. باید راهی پیدا کنیم تا قبیله‌های دیگر را یکپارچه کنیم و یکصدا با Twilight's Blade بجنگیم.\nبا نماینده‌های قبیله‌ها حرف می‌زنم و تا جایی که بتوانم به پناهجویان کمک می‌کنم؛ آن‌ها اولویت ما هستند.\nبیا؛ شاید چیزهایی دربارهٔ Amani یاد بگیری.", o = { "با Torundo برای پناهجویان Atal'Aman غذا آماده کن", "از Lilaju گزارش Lightwood را بگیر", "از Tak'lejo شمن‌های Shadowpine را بخواه", "با Kinduru صحبت کن", "در نیایشگاه دهکدهٔ Amani'Zar با Zul'jarra دیدار کن." }, p = "اگر نیاکان بخواهند، به‌زودی فرصت ضربهٔ متقابل را پیدا می‌کنیم.", c = "Hash'ey؟ عمو عقلش را از دست داده؟\nاین قصهٔ بچه‌هاست. شاید اگر روزهای قدیم بود، نسل‌ها پیش، قبل از رسیدن الف‌ها...\nاما اگر آخرین شانسی که داریم این است که تلاش کنیم با loa حرف بزنیم، پس تلاش خواهم کرد." }
WoWFQ[86653] = { t = "راه Amani", d = "Kinduru عموی من است و به او اعتماد دارم... اما این «راه hash'ey»...\nچیزها آن چیزی نیستند که ده‌ها سال پیش بودند. loaها رفته‌اند؛ قرار نیست به ما گوش دهند.\n<Zul'jarra lets out a low growl only you and Liadrin hear.>\nنه. گزینه‌هایمان رو به اتمام است. اگر وقت افسانه‌های قدیمی و رؤیاهاست، پس همین باشد.\nدر پای کوه‌ها به هم می‌رسیم، در Akil'zon's Reach، همان‌جا که نیایشگاه‌های قدیمی hash'ey هستند.", o = { "در Akil'zon's Reach با Zul'jarra دیدار کن", "کمی بمان و گوش کن" }, c = "این راه پر از gnarldin است.\n<Zul'jarra smiles broadly.>\nکاش جلوی ما را بگیرند. می‌توانم تیغم را روی استخوان‌هایشان تیز کنم." }
WoWFQ[86654] = { t = "کوبیدن gnarldin‌ها", d = "Zul'jarra gnarldin‌ها را قومی وحشی و کوچ‌نشین می‌داند که معمولاً به کار خودشان مشغول‌اند. از لباس‌ها و سلاح‌هایشان پیداست که فرهنگی ابتدایی اما یکتا دارند.\nاگر شرایط فرق می‌کرد، من طرفدار دیپلماسی بودم.\nاما آن‌ها بین ما و مأموریتمان قرار گرفته‌اند.\nنمی‌توانند راه ما را سد کنند یا به آسیب‌زدن به نیایشگاه‌ها یا لانهٔ عقاب‌هایی که این‌جا آشیانه دارند ادامه دهند. فقط آن‌هایی را از بین می‌بریم که سر راه‌مان باشند. بعداً خود Amani‌ها انتخاب می‌کنند با بقیه چه کنند.", o = { "gnarldin کشته‌شده", "در پای معبد Akil'zon با Liadrin دیدار کن." }, p = "به نظر می‌رسد gnarldin‌ها آمادهٔ جنگ با ما هستند. بگذار همان چیزی را به‌شان بدهیم که می‌خواهند، چه می‌گویی؟", c = "خوب است. امیدوارم این راهِ رسیدن به نیایشگاه‌ها و معبد را تا حد نیازمان باز کرده باشد." }
WoWFQ[86655] = { t = "راه باستانی", d = "عمویم، گویندهٔ loa، وقتی بچه بودم از hash'ey می‌گفت. اما وقتی loa این‌همه سال خاموش ماند...\nفکر نمی‌کنم اعتراف کند، اما او هم کمی ایمانش را از دست داد.\nبعضی از درس‌هایش را به یاد دارم.\nیک رئیس قبیله باید در راه معبد نیایشگاه‌ها را روشن کند. hash'ura‌ها هم همین‌طور. چرا؟ یادم نیست.\nاما اگر تنها راه جلب لطف loa همین است؟ بیا. این را سرِ راه حلش کنیم.", o = { "نیایشگاه hash'ey عقاب روشن‌شده", "نیایشگاه پایانی hash'ey عقاب روشن‌شده", "در پای معبد Akil'zon با Zul'jarra دیدار کن." }, p = "امیدوارم این کار را درست انجام می‌دهیم.", c = "نیایشگاه‌ها روشن شدند.\nحالا چه کار کنیم؟" }
WoWFQ[86656] = { t = "ضیافت بی‌رحمانه", d = "<Zul'jarra's brow furrows and her lip curls as she looks toward the temple.>\nوقتی آخرین نیایشگاه را روشن کردیم، بعضی از عقاب‌ها به معبد برگشتند. می‌تواند یک نشانه باشد.\n<Zul'jarra scoffs.>\nیا عقاب‌ها بعد از اینکه gnarldin‌ها شروع کردند به رفتن، دارند جا باز می‌کنند.\nوقتی به معبد برسیم، چیزی جز سکوت پیدا نمی‌کنیم. مثل همیشه.\nاما با این حال تلاش می‌کنیم. بهتر است حالا برویم و پیشکشی بدهیم.", o = { "در معبد Akil'zon با Zul'jarra دیدار کن", "کمی بمان و گوش کن", "سرهای gnarldin را از کیسه بیرون بیاور", "سرهای gnarldin گذاشته‌شده" }, c = "آن صدا...\nتو هم شنیدیش، <Name>؟" }
WoWFQ[86657] = { t = "Shadebasin Watch", d = "<Zul'jarra smiles slightly as Akil'zon's blessing buffets her.>\nقصه‌های Kinduru واقعی بودند. برکت Akil'zon را داریم و راه hash'ey پیش روی ما کشیده شده است.\nباید نصیحت Akil'zon را دنبال کنیم و بعد سراغ Halazzi برویم. همان‌طور که Akil'zon loaی قبیلهٔ حاکم — یعنی Amani — و خانوادهٔ من است، Halazzi loaی Witherbark و رهبرانشان است.\nاگر گوینده‌های loa آن‌ها رفته‌اند، شاید Kul'amara بداند چطور باید نزدیکش شد.", o = { "کمی بمان و گوش کن", "در Shadebasin Watch با Kul'amara دیدار کن" }, c = "Vilebranch‌ها خیلی طولانی قوم من را عذاب داده‌اند.\n<Zul'jarra glares in fury at the nearby Vilebranch village of Maisara.>\nخیلی وقت است راهش را می‌رویم، اما حالا وقت درگیری با آن‌هاست." }
WoWFQ[86658] = { t = "آرامگاه در مه", d = "<Zul'jarra growls through her gritted tusks.>\nحالا دیگر تعجب‌آور نیست که قبیلهٔ Malacrass، یعنی Vilebranch، وسوسهٔ جادوی نفرین شده باشد.\nاما این انتخاب آن‌هاست و راهی که خیلی پیش انتخابش کردند — راهی دور از ما.\nاجازه نمی‌دهم آن‌قدر زنده بمانند که پشیمان شوند.\nکاری که Vilebranch‌ها با Witherbark‌ها کرده خیلی طولانی بی‌پاسخ مانده است. مه سر راه ما نیست.\nمی‌توانیم از آن به نفع خودمان استفاده کنیم.\nدر برابر همهٔ جان‌هایی که گرفته‌اند، یک جان می‌گیریم. و مطمئن می‌شویم که مرده بمانند.", o = { "ورودی آرامگاه پیدا شد", "ترول‌های Vilebranch کشته‌شده", "آیین‌گر Zongha کشته‌شده", "بیرون آرامگاه Numazon با Zul'jarra دیدار کن." }, p = "پیدا کردن Halazzi می‌تواند صبر کند. Vilebranch‌ها شکارِ قوم من شده‌اند. وقتش رسیده که بعضی شکارچی‌ها به‌شان شکار شوند.", c = "<Zul'jarra spits on the ground.>\nحال‌به‌هم‌زن است. لایق آن‌اند که برگردند و صد بار کشته شوند.\nامیدوارم هر loaیی که در جهان دیگر منتظرشان است، آن‌ها را درو بکَد و با دندان‌های آسیابش بجود." }
WoWFQ[86659] = { t = "گذر از مه", d = "به نظر می‌رسید Vilebranch‌ها هم دقیقاً مثل Witherbark‌ها از مه گیج شده بودند.\nهر چه هم که باعث این مه شده، درگیری با Vilebranch‌ها هیچ چیز را عوض نکرد.\nو حالا باید نیایشگاه‌های hash'ey را در تاریکی پیدا کنیم.\n<Zul'jarra moves her hand in front of her face, testing her range of visibility, and frowns.>\nباید نیایشگاه‌ها را روشن کنیم. حواست باشد از هم جدا نشویم.\nاین صبرم را می‌آزماید. اما مطمئنم اگر عقلمان به کار بیاید، راه را پیدا می‌کنیم.", o = { "اولین نیایشگاه hash'ey پیدا شد", "نیایشگاه hash'ey سیاه‌گوش فعال شد", "آخرین نیایشگاه hash'ey سیاه‌گوش فعال شد", "در معبد Halazzi با Zul'jarra دیدار کن." }, c = "پیدا کردن Halazzi و نیایشگاه‌های hash'ey به من صبر آموخت. و وادارم کرد به موانعم فکر کنم، به جای اینکه راه‌ام را از میانشان باز کنم.\nکاش Zul'jan این‌جا بود. از اینکه کمی عقل به سرم زده به من می‌نازید. هه." }
WoWFQ[86660] = { t = "نجات از سایه‌ها", d = "Kul'amara به من گفت که مه‌ای سایه‌مانند بر Numazon افتاده. او باور دارد Vilebranch‌ها پشت آن هستند و با جادویشان جنایت‌هایی را که علیه Witherbark‌ها می‌کنند پنهان می‌کنند.\nباور دارد در آرامگاه‌های Numazon مخفی شده‌اند. نیایشگاه‌های hash'ey هم نزدیک همان‌جاست.\nباید راه‌مان را به Numazon پیدا کنیم و اسیران Witherbark را نجات دهیم. اگر در این میان به نیایشگاه‌های hash'ey برسیم، همین بهتر.\nاگر Halazzi با ما نایستد، شاید Witherbark‌ها بایستند.", o = { "Witherbark‌های اسیر آزادشده", "بیرون آرامگاه Numazon با Zul'jarra دیدار کن." }, p = "مراقب اسیران Witherbark بیشتری باش!", c = "پس دلیلش این بود که Vilebranch‌ها دنبال Witherbark‌ها بودند — برای خوشنود کردن Twilight's Blade با دادن سربازهای بیشتر به‌شان.\nسربازهای مردگان. سربازهای مطیع.\nو ما همین حالا هم خیلی‌ها را از دست داده‌ایم." }
WoWFQ[86661] = { t = "زغال‌های loaی مرده", d = "با کمک به Witherbark‌ها، به خودمان کمک کردیم — و آزمون Halazzi را پاس کردیم.\nدر این دردی نهفته است.\nحالا که Halazzi برگشته، باید برگردیم و به Vun'zarah خبر دهیم. امیدوارم این رابطهٔ قبیله‌های‌مان را بهتر کند.\nو شاید او بداند از کجا می‌توانیم بفهمیم چطور می‌شود Jan'alai را دوباره زنده کرد.", o = { "با Vun'zarah صحبت کن" }, p = "تا این‌جا آمده‌ایم. باید تلاش کنیم loaی مرده را دوباره زنده کنیم.", c = "«گویندهٔ loaی عجیب‌وغریب.»\nهه. آشنا به نظر می‌رسد. به‌نظر همه‌شان همین‌طورند." }
WoWFQ[86663] = { t = "از اخگر تا شعله", d = "<Zul'jarra زغال توی مشتش را وارسی می‌کند. گرمای عجیبی می‌دهد، اما اگر دارد می‌سوزاندش، بروزش نمی‌دهد.\nگویندهٔ loa از آتش در دل حرف می‌زند — در همهٔ دل‌ها.\nJan'alai loaی تولد، مرگ و تولد دوباره است. شاید گویندهٔ loa خواهان قربانی است.\n<Zul'jarra smiles deviously.>\nهی، Liadrin. به نظرت چقدر آتش در دل یک الف هست، ها؟\n<Liadrin gives her a sour look.>\nهه.\nهر چیزی هم که گویندهٔ loa می‌خواهد، یا بخشی از زنده‌کردن دوبارهٔ loa است یا بخشی از آزمون. ببینیم چه می‌گوید.", o = { "کمی بمان و گوش کن", "زغال Jan'alai را بردار", "زغال Jan'alai قدرت گرفت", "زغال قدرت‌گرفته گذاشته‌شده" }, p = "این گویندهٔ loa مثل Kinduru به ایمانش چسبیده. اما Kinduru بلد است منظورش را شفاف بگوید. معمولاً.", c = "<Zul'jarra watches the flames dance in the coals. A small smile creeps up on her face. She balls her fists and flexes her arms.>\nفکر کنم این آزمون همین حالا شروع می‌شود.\nهر چه هم سر راهم بگذارد... آماده‌ام!" }
WoWFQ[86664] = { t = "بینا یا سوزان", d = "این گویندهٔ loaی پیر و دیوانه آن‌قدر مشغول رقصیدن است که نمی‌گوید بعد چه باید بکنیم.\nاما فکر کنم خودم می‌دانم.\nنشد نیایشگاه‌ها را در راه معبد روشن کنیم. اما حالا که Jan'alai این‌جاست...\nشاید حالا بشود.\nاخگر را به نیایشگاه‌های hash'ey می‌برم. شاید بعدش آزمون شروع شود.\nاز نوک معبد Akil'zon پریدم. راه‌ام را از میان مه‌های Halazzi پیدا کردم.\nبرای آتش Jan'alai آماده‌ام.\nفقط می‌توانیم امید داشته باشیم که بعد از کاری که پدربزرگم کرده، ما را بپذیرند.", o = { "اولین نیایشگاه hash'ey روشن‌شده", "دومین نیایشگاه hash'ey روشن‌شده", "Coalesced Flame گذاشته‌شده" }, p = "دیگر جلوی آزمون را نمی‌شود گرفت. باید هر چه لازم است بکنیم.", c = "<Zul'jarra brushes some ash off her shoulder.>\nشعلهٔ Jan'alai... شک‌ها را از دلم گرفت و به‌شان صورت و شکل داد.\nمن... برای چنین چیزی آماده نبودم.\nچه چیزهای دیگری در آستین دارند؟" }
WoWFQ[86665] = { t = "چهره در آتش", d = "اول پدربزرگم، بعد برادرم.\nJan'alai شرمی را که از خشم پدربزرگم داشتم می‌دانست. و خشمی را که وقتی Zul'jan به من بی‌احترامی می‌کند حس می‌کنم. می‌دانم با جواب‌دادن به آن شکل، خودم آتشش را تندتر می‌کنم.\nشاید باید این عوض شود. شک به loa را پشت سر گذاشتم. می‌توانم آن فکرها را هم پشت سر بگذارم و راه hash'ey را ادامه دهم.\nزغال را هم بزن، <name>. برای آزمون آخر، هر چه که باشد، آماده‌ام.", o = { "زغال لمس شد", "Final Manifestation کشته‌شده" }, p = "بگذار این را تمامش کنیم.", c = "خوش می‌نشیند که آخرین آزمون رو‌به‌رو شدن با شک خودم باشد. دربارهٔ رهبری‌ام و انتخاب‌هایم.\nحال‌آور بود. انگار شک آب شد و رفت.\nو باید بگویم... تا حالا شعله‌های این‌قدر خوش‌فرم و خوش‌تیپ ندیده بودم.\n<Zul'jarra, despite it all, laughs heartily and claps you on the shoulder.>" }
WoWFQ[86666] = { t = "در سایهٔ تولد دوباره", d = "آزمون Jan'alai باعث شد بفهمم...\nباید اوضاع را بین خودم و برادرم درست کنم.\nاو به من پرخاش می‌کند، اما دلیلش این است که من تحقیرش می‌کنم. به این فکر نمی‌کنم که برادرِ من بودن چقدر سخت است.\nباید هم ببینیم آماده‌مان چطور پیش می‌رود و سربازانم غذا و استراحتی که لازم دارند را می‌گیرند یا نه.\nNalorakk جای هیچ‌جا نمی‌رود. می‌تواند چند ساعت صبر کند.", c = "این‌همه کشته..." }
WoWFQ[86681] = { t = "لانهٔ Nalorakk: چشیدن انتقام", d = "Zul'jan بدون دستور من سربازها را برده — باز هم!\nو تعداد کشته‌ها... برای چی؟ برای چوب؟\nحیف شد عاج‌هایش را نکَنم و...\n<Zul'jarra growls but seems to center herself.>\nKinduru برای آیین مرگ سربازها کمک لازم دارد. در آماده‌کردن آمیزهٔ گیاهی به او کمک کن و روی آتش‌ها بریزش.\nمن و برادرم باید... حرف بزنیم.", o = { "با هاون Kinduru Bog Herbs را بکوب", "Death Rites Mixture را روی آتش‌ها بریز" }, p = "تعدادمان خیلی کم شده. برادرم به چه فکر می‌کرد؟", c = "برادرم را دوست دارم. مثل روز و شب با هم فرق داریم. با این حال، بچه که بودیم به هم نزدیک بودیم.\nZul'jan باهوش است اما نمی‌فهمد. پیروزی وقتی هیچ‌کس نمانده باشد که جشنش بگیرد، هیچ است.\nاو باید دست راست من باشد، نه دردسرِ من.\nامیدوارم Zul'jan را آن‌قدر بدون راهنما رها نکرده باشم که دیگر نتوانم سر جایش برگردانم." }
WoWFQ[86682] = { t = "لانهٔ Nalorakk: بیدارکردن خرس", d = "باید کاری که Zul'jan کرده را کنار بگذاریم و روی آزمون آخر hash'ey تمرکز کنیم: رو‌به‌رو شدن با Nalorakk، loaی جنگ.\nRevantusk‌ها روزگاری محبوب Nalorakk بودند. افسانه می‌گوید گویندهٔ loa‌اش چنان فداکار بود که همراه وفادارترین جنگجویان Revantusk او را تا معبدش و لانه‌اش دنبال کرد.\nاما حالا معبد مهر و موم شده. نمی‌توانیم با گویندهٔ loa حرف بزنیم، اما شاید Lilaju بداند چطور باید توجه Nalorakk را جلب کرد.\nاو با نگهبانانش در Torntusk Overlook حواسش به Twilight's Blade است.", o = { "با Lilaju صحبت کن" }, p = "Lilaju تنها کسی است که حالا می‌تواند به ما کمک کند.", c = "دلسوزی برای Lilaju ندارم — من هم تقریباً همسن او بودم که جای رهبر Amani‌ها را گرفتم.\nبه او می‌نازم. برای خودش و قبیله‌اش می‌ایستد.\nهر چه لازم داشتیم به ما داد. و از قولم که به کمکش می‌آیم برنمی‌گردم." }
WoWFQ[86683] = { t = "دور شدن با hash'ey", d = "انجامش دادیم، <name>. loaها یک بار دیگر پشتمان هستند.\nآیا من hash'ey هستم؟ نمی‌دانم. اما این را می‌دانم که بدون hash'ura‌هایم تا این‌جا نمی‌رسیدم.\nبیا. به Amani'Zar برمی‌گردیم و خبر خوش را به Kinduru و Zul'jan می‌دهیم.", o = { "رسیدن به دهکدهٔ Amani'Zar", "با Zul'jarra صحبت کن" }, p = "همهٔ جنگجویانمان کجا هستند؟", c = "حالا این یکی جنگ می‌شود!" }
WoWFQ[86684] = { t = "لبهٔ تیغ", d = "با کمک قبیله‌های دیگر و loaها، می‌توانیم جنگ را به Twilight's Blade ببریم و سرشان را به‌خاک بمالیم.\nخون، در برابر خون!", o = { "رسیدن به Broken Throne", "در Broken Throne با Zul'jarra و Liadrin دیدار کن." }, c = "<Zul'jarra's piercing eyes survey the battlefield. She mutters under her breath what you can only imagine are troll profanities. You hear her say \"Jan\" among them.>\nمیدان پر از جسد است. جسد قوم من. اما هنوز خیلی‌ها در جنگ‌اند!\nهنوز وقت هست چرخهٔ نبرد را برگردانیم!" }
WoWFQ[86685] = { t = "تراشیدن و خردکردن", d = "<Zul'jarra سرش را این‌سو و آن‌سو تکان می‌دهد، سر جایش می‌پرد و عضلاتش را می‌لرزاند.\nمی‌ایستد و با لبخندی پهن رو به تو می‌شود.>\nهه. حسش می‌کنی، hash'ura‌ام؟\nبرق را در هوا؟ بوی خون و آتش را؟\nجانم برای پیوستن به جنگ می‌جنبد.\nآماده‌ای دشمن را از پا درآوری، در خونش شنا کنی و جواب کاری را که کرده‌اند بدهی؟\nمن هم همین‌طور.", o = { "Twilight's Blade کشته‌شده" }, p = "و دست نمی‌کشی تا اینکه همه‌شان مرده باشند.", c = "خوب بود.\nاما هنوز تشنهٔ بیشتری‌ام." }
WoWFQ[86686] = { t = "نور بی‌ملاحظه", d = "هرچند مرده‌ها این میدان را پر کرده‌اند، هنوز بسیاری از Amani‌ها را می‌بینم که به زندگی چسبیده‌اند.\nدر شفا دادن زخمی‌ها کمکم کن. مراقب خواهیم بود آوازه‌شان در زنده‌ماندن، بعد از امروز هم ادامه پیدا کند.", o = { "جنگجوی زخمی Amani شفا یافته" }, p = "هر جنگجویی که شفا بگیرد، یک شمشیر دیگر در کنار ماست!", c = "بی‌تابم ببینم وقتی گزارش می‌دهم قیافهٔ Lor'themar چه شکلی است.\n<A slight smile creeps across Liadrin's blood-spotted jaw.>\nحتماً می‌ارزد که بیشتر از توبیخ حتمی‌ام باشد." }
WoWFQ[86687] = { t = "بحران رساناها", d = "با loaها در کنارمان، سرانجام می‌توانیم Twilight's Blade را بشکنیم و با سر Mor'duun به Amani'Zar برگردیم.\nloaها دارند به منبع اصلی قدرت Mor'duun حمله می‌کنند: گوی‌های احضارشده از انرژی خالصِ تهی.\nنزد loaها برو و کمکت را عرضه کن. وقتی گوی‌ها نابود شدند، می‌توانیم پیش برویم و به Mor'duun بزنیم!", o = { "رساناهای نزدیک Jan'alai نابودشده", "رساناهای نزدیک Halazzi نابودشده", "رساناهای نزدیک Akil'zon نابودشده", "رساناهای نزدیک Nalorakk نابودشده" }, p = "نترس. اگر به‌شان کمک کنی، loaها قدرتشان را به تو می‌بخشند.", c = "دیدن loaها که کنارشان می‌جنگند، جنگجویانمان را پر از امید کرد.\nیادشان آمد که Amani هستند!" }
WoWFQ[86692] = { t = "تیغ شکست", d = "این‌جا به پایان می‌رسد. راه hash'ey، راه من، مرا به این‌جا رساند.\nبگذار این جنگ روزگار تازه‌ای برای قوم من بیاورد.\nبیا. وقتش است.", o = { "با Zul'jarra صحبت کن", "Mor'duun کشته‌شده" }, c = "<Zul'jarra snorts and spits out a viscous wad of blood, broken tooth included.>\nتمام شد." }
WoWFQ[86693] = { t = "افسانهٔ hash'ey", d = "Mor'duun کشته شد.\nTwilight's Blade به آزار سرزمین‌های‌مان ادامه می‌دهد، اما از آن‌ها فقط «خوراک‌مرغ»های Mor'duun مانده. برای ما شکار راحتی خواهند بود.\nو حالا چیزی می‌گویم که عمویم به آن می‌نازید. بیایید از آموختهٔ Nalorakk، loaی جنگ، پیروی کنیم.\nنبرد تمام است. وقت استراحت است — از چشم‌هایت می‌فهمم که هر دو hash'ura‌ام به آن نیاز دارند.\nاین‌جا را ترک کنیم. در Amani'Zar دوباره حرف می‌زنیم.", o = { "در دهکدهٔ Amani'Zar با Zul'jarra حرف بزن." }, p = "امیدوار بودم بالاخره بتوانم استراحت کنم.\nاما به‌نظر می‌رسد وقت جشن است!", c = "حتی به دلم نرسیده بود که آن چه جشن می‌گیریم... خود من باشم.\nاز پیش از جنگ الف‌ها و انسان‌ها، هزاران سال پیش، hash'ey در میان Amani‌ها نبوده است.\nافتخار بزرگی است، اما مطمئن نیستم هنوز لایقش باشم.\nتلاش می‌کنم به‌شان باشم." }
WoWFQ[86711] = { t = "فراخوان Amani", d = "اگر می‌خواهی در Atal'Aman زنده بمانی، طبل‌های جنگی شهر را پیدا کن و بکوب. این‌کار باقی سربازانمان را به میدان می‌فرستد تا به جنگ بپیوندند.\nهمچنین همهٔ قبیله‌های Zul'Aman — Witherbark، Revantusk و Shadowpine — را برای کمک به‌دمان می‌آورد و به مردم عادی‌مان می‌گوید اگر لازم شد تخلیه کنیم، به Altar of Malacrass عقب بکشند.\nاز طبل‌ها برای رساندن پیام استفاده کن. کارت تمام شد، در Altar of Malacrass به من بپیوند.", o = { "طبل جنگی Amani به صدا درآمد", "Zul'jarra را در شرق Atal'Aman پیدا کن." }, c = "خیلی از Amani‌ها راه‌شان را تا این‌جا پیدا کردند، اما باید به بیشترشان کمک کنیم.\nو دشمنان حتی بیشتری برای کشتن." }
WoWFQ[86712] = { t = "Amani‌ها محکم می‌ایستند", d = "Zul'jarra فکر می‌کند Lightwood ارزش ریسکی را که می‌کنم ندارد. ما به‌اش ثابت می‌کنیم که اشتباه می‌کند.\nخیلی جنگجویان را دیده‌ام که دل‌سرد شدند چون سلاح‌های‌شان علیه Twilight's Blade کار نمی‌کند.\nفقط نگو عقب بکشند. سلاح‌های lightwood را به‌شان بده.\nهیچ چیز خون Amani را مثل یک تبر کارآمد توی دست گرم نمی‌کند. بگذار با همین‌ها راه‌شان را تا Altar of Malacrass باز کنند.", o = { "مدافع دلسرد مسلح شد", "Lightwood Weapon (ارائه‌شده)", "Zul'jan را در Altar of Malacrass پیدا کن." }, p = "قوم من را مسلح کن — بعد دوباره حرف می‌زنیم.", c = "سربازانی که مسلح کردیم، خیلی از Twilight's Blade را کشتند.\nبعضی‌شان زنده ماندند و راه‌شان را تا این‌جا پیدا کردند.\nچند نفر را هم از دست دادیم، اما فکر می‌کنم این قربانی می‌ارزید." }
WoWFQ[86715] = { t = "آیین‌های نیمه‌کاره", d = "در پرواز شناسایی‌مان دور شهر، من و Zul'jarra نگاهی به حملهٔ Twilight انداختیم. دارند Twilight's Blade را مستقیم داخل Atal'Aman احضار می‌کنند.\nمی‌توانیم با به‌هم‌زدن آیین‌های احضار تاریکشان جلوی‌شان را بگیریم. این جریان فرقه‌گرایانشان را به شهر می‌بندد و به Amani‌ها فرصت نقشه‌کشی می‌دهد.\nآیین‌گرها را بکش، و هر trollbreaker‌ای که از قبل با دروازه به این ناحیه رسیده را هم.", o = { "آیین‌گر Twilight کشته‌شده", "Trollbreaker Twilight کشته‌شده", "Liadrin را در Altar of Malacrass پیدا کن." }, p = "نمی‌توانیم اجازه دهیم Twilight's Blade حتی یک سرباز دیگر به Atal'Aman بیاورد.", c = "این باید کارشان را کند کند — دست‌کم فعلاً." }
WoWFQ[86716] = { t = "مسلح به نور", d = "شاید در کشتن دستت خوب باشد، <Class>، اما ما Amani‌ها هم همین‌طوریم.\nو هرچه سلاحمان بهتر، بهتر هم!\nیک ارتش به Eversong بردم تا جنگل‌های lightwood را برای Amani‌ها پس بگیرم. برخلاف دستور خواهرم بود، بله، اما lightwood برتری به ما می‌دهد.\nسلاح‌هایی را که Twilight's Blade دارد می‌دزدد پس بگیر تا نشانت بدهم چرا ارزشش را داشت.", o = { "Lightwood Weapon", "سلاح‌ها را به Zul'jan در جنوب‌غربی Atal'Aman برسان." }, p = "این سلاح‌ها مرز بین زنده‌ماندن و مردن قوم من‌اند.", c = "خوب است.\nحالا دندان‌هایی داریم که با آن‌ها گاز بگیریم." }
WoWFQ[86717] = { t = "ارزش‌ات را به ما نشان بده", d = "ژنرال Twilight's Blade، یعنی Mor'duun، گلوی‌مان را گرفته. نمی‌جنگیم، و تعدادمان هم خیلی کم است.\nباید قبل از اینکه کسی نماند تخلیه کنیم — و امید داشته باشیم قبیله‌های دیگر ما را در Amani'Zar پیدا کنند.\nدر این میان، تا مردم Zul'Aman را جمع می‌کنیم، خوشحال می‌شوم از تو استفاده کنم.\nجان مردم عادی اولویت من است. برو به Swiftclaw Terrace و مردم آن‌جا را تخلیه کن.\nموقع رفتن از میان Twilight's Blade بشکاف. کارت تمام شد خودت را به Zul'jan برسان.", o = { "نیروهای Twilight را درهم بشکن", "با Zul'jan در شمال Atal'Aman دیدار کن." }, p = "اندامشان را از هم جدا کن. پرچم‌ها و سرپناه‌های‌شان را هم به‌هم بریز!", c = "راه را باز کردی، اما Mor'duun همچنان ما را سرگردان و بی‌تعادل نگه می‌دارد.\nبرای تمام‌کردن این ماجرا به هرچه سلاح lightwood هست نیاز داریم." }
WoWFQ[86718] = { t = "خون‌ریختهٔ Twilight", d = "Mor'duun شاید فرماندهٔ Twilight's Blade در Zul'Aman باشد، اما آن اُگر نمی‌تواند همه‌جا باشد. آن الف فرماندهٔ نظامی‌اش را پیدا کرد — توده‌ای سترگ از زره و گوشت به نام Benvis Bladesplatter.\nآن‌قدر می‌گردد و دست‌پا می‌زند انگار برده، فقط چون Firewing Terrace را گرفتند.\nحساب غرورش را برس.", o = { "Benvis Bladespatter کشته‌شده", "Zul'jarra را در Altar of Malacrass پیدا کن." }, p = "کشتش یا هنوز؟", c = "بعدی که سرنگون می‌شود Mor'duun است." }
WoWFQ[86719] = { t = "Amani‌های مهم", d = "طبل‌ها به صدا درآمدند. اما سالخوردگان نیامدند.\nنمی‌توانیم آن‌ها را از دست بدهیم. آن‌ها پیوند ما با فرهنگمان‌اند — دانایان و بهترین ذهن‌های ما.\nTorundo در ساخت سلاح‌های lightwood کمک کرد. و Doru آذوقه‌رسان ماست. اگر جنگ ادامه پیدا کند، به هر دو نیاز داریم.\nبرو Doru را در بازار پیدا کن و Torundo را در تالار پیشکش‌ها.\nآخری گویندهٔ پیر loa است — عمویم Kinduru. شاید برای ترک این‌جا... راضی‌کردن خاصی بخواهد. من به Talonstrike Terrace می‌روم تا با او حرف بزنم. بقیه را پیدا کردی، آن‌جا به من بپیوند.", o = { "به Doru سالخورده بگو تخلیه کند", "به Torundo the Grizzled بگو تخلیه کند", "به Kinduru بگو تخلیه کند", "دنبال Hash'ey Staff بگرد", "Hash'ey Staff" }, p = "هر چه لازم است بکن تا Kinduru برود.\nعموی ماست. نمی‌توانیم این‌جا رهایش کنیم.", c = "عقاب‌ها... loaها... وقتی برای ماندن در روح‌های گذشته نداریم." }
WoWFQ[86720] = { t = "شکستن تیغ", d = "بالستای Zul'jan آماده است. و بعد از کاری که کرده، بهتر است کار کند.\nارتشی که برای دفاع از شهر لازم داشتیم را از دست دادیم، اما می‌توانیم تا وقتی مردممان فرار کنند جلوی Mor'duun را بگیریم.\nبه برادرم در فرماندهی بالستا کمک کن. روی Shadow Ward و ستون تمرکز کن. من و Liadrin حواس Mor'duun را پرت می‌کنیم.\nاگر بتوانم می‌کشمش، اما حتی آن موقع هم نمی‌توانیم بمانیم. انرژی تهی خیلی زیاد است. و ویرانی هم زیاد. Atal'Aman واقعاً از دست رفت.", o = { "Lightwood Ballista استفاده شد", "Shadow Ward نابود شد", "دفاع‌های Mor'duun نابود شد", "Morduun's Pylon نابود شد" }, c = "<Zul'jarra seethes with rage.>\nMor'duun با ما بازی می‌کند. می‌توانست بماند و شهر را یک‌جا نابود کند.\nاگر نقشهٔ Twilight's Blade آشفتگی است، باید آماده شویم." }
WoWFQ[86721] = { t = "هر آن چه برایش تلاش کردیم", d = "خونم دارد می‌جوشد! در حالی که منتظر Kinduru بودیم، Twilight's Blade داشت آخرین ذخیره‌های lightwood‌مان را در Ragemaw Terrace می‌سوزاند!\nاما اگر سریع حرکت کنیم، می‌توانیم به‌اندازهٔ مسلح‌کردن بالستای lightwood نجاتشان بدهیم — و شلیکی هم به سمت Mor'duun داشته باشیم.\nو بدون بالستا، پیروزی مال ما نمی‌شود!", o = { "آتش‌های lightwood خاموش شد", "تودهٔ بزرگ lightwood خاموش شد" }, p = "بگذار lightwood بسوزد، نه!", c = "خیلی زیادی از آن را از دست دادیم...\nمی‌توانستیم با پرتابه‌های بالستا آسمان را سیاه کنیم!\nاما شاید همین هم کافی باشد. باید کافی باشد!" }
WoWFQ[86722] = { t = "قلب Amani", d = "تو و دوست الفت مرا سرگرم می‌کنید. و در میدان نبرد هم بیشتر از حد ثابت کرده‌ای.\nمردممان به سمت Amani'Zar می‌روند. امید داریم قبیله‌های دیگر به‌جای Atal'Aman آن‌جا جمع شده باشند. نماینده‌های‌شان به ما مشورت می‌دهند و بعد به Twilight's Blade حمله می‌کنیم.\nاگر هنوز می‌خواهی با Amani‌ها بجنگی، در شمال‌غربی دهکده به من بپیوند. Zul'jan جلوتر رفته تا از کارهایش — و کارهای تو — بگوید، اما بدون من وارد دهکده نشو. Amani‌ها غریبه را همان‌جا که ببینند می‌کشند.", o = { "در دهکدهٔ Amani'Zar با Zul'jarra دیدار کن." }, c = "Tokobo'ne na Amani'Zar، <name>. به Amani'Zar خوش آمدی.\nچون مهمان من هستی، قوم من به تو آسیبی نمی‌زنند... مگر اینکه بگویم.\nبهانه‌ای دستم نده، باشد؟" }
WoWFQ[86723] = { t = "انزوا", d = "با Torundo، مشاور جنگی‌ام، حرف خواهیم زد. و اگر نماینده‌های قبیله‌ها این‌جا باشند، در Zari Lodge جلسهٔ شورا می‌گذاریم.\nباید با هم روی راهی برای شکست دادن Twilight's Blade به توافق برسیم.\nاگر دوست داری دهکده را بگرد. اما سلاحت را آن‌قدر بگذار که دیده شود. با دعوت من این‌جایی و حرف من قانون است، اما اگر یکی از قومم فکر کند بد نگاهش کرده‌ای، من فقط می‌توانم این‌قدرها تند بدوم.\n<Zul'jarra smiles a tusky grin as if proud of her people's short fuse.>", o = { "در Village Hall با Zul'jarra صحبت کن" }, p = "به نظر مشاورم، Torundo، نیاز دارم. و باید بفهمیم چرا قبیله‌های دیگر به طبل‌ها گوش ندادند.\nشاید فکر کنند ناچارم که از تو کمک بخواهم. اما جرات ندارند با من درافتند.", c = "چیزهای زیادی هست که... تو از ما و loaها نمی‌دانی." }
WoWFQ[86808] = { t = "گویندهٔ چیستان‌گو", d = "رئیس قبیله Vun'zarah کم از Jan'alai می‌دانست، اما گویندهٔ loaشان را می‌شناخت.\nاگر هنوز در معبد باشند، امیدی هست که بتوانیم loa را دوباره زنده کنیم.\n<Zul'jarra's hand tightens on her axe.>\nفراری‌دادن Akil'zon، زخمی‌کردن Halazzi، دیوانه‌کردن Nalorakk، و کشتن Jan'alai...\nپدربزرگم و Malacrass حساب خیلی زیادی دارند پس بدهند.", o = { "در معبد Jan'alai با Zul'jarra دیدار کن" }, c = "«خودت را پاک کن، تا برخیزد.»\nکاش Zul'jan را آورده بودم. همیشه در چیستان‌گویی دستش بود." }
WoWFQ[86809] = { t = "آزمون پایداری", d = "توجه‌اش را جلب کردیم. اما حالا چه؟\nمی‌دانم آزمونی در میان است. اما Akil'zon هیچ سرنخی از جنس آزمون نمی‌دهد.\nفکر کن. فکر کن. Kinduru بچگی چه به من آموخت؟ او loaی پیروزی است. اما همچنین loaی سوگند و ایمان راسخ.\nکاش بچگی از آن بالای معبد بالا می‌رفتیم و نمی‌افتادم...", o = { "به لبهٔ معبد رسیدی", "بپر!" }, c = "<Zul'jarra's eyes are closed. She seems lost in thought.>\nهمیشه این‌جا بودند. تقصیر پدربزرگم بود که جوابمان را نمی‌دادند.\n<She nods her head and sighs.>\nپدربزرگم این را شکست. درست‌کردنش با من است. تنها راه نجات قوم من همین است." }
WoWFQ[86868] = { t = "گشت دوستی", d = "وضعیت این‌جا خیلی بدتر از چیزی است که تصور می‌کردم.\nTwilight's Blade و رهبرشان Mor'duun شهر را کامل در دست گرفته‌اند.\nاز همین فرصت استفاده می‌کنیم تا به Amani‌ها نشان دهیم چقدر در نابودکردن نیروهای تهی کارآمدیم. شاید کمک کند قانع شوند دست‌کم تا رفع این خطر، خصومت میان قوممان را نگه دارند.", o = { "سایه‌های مهاجم کشته‌شده", "در شهر Atal'Aman با Liadrin، Zul'jarra و Zul'jan دیدار کن." }, p = "Zul'jarra در مقایسه با برادرش خیلی عمل‌گرا به‌نظر می‌رسد.", c = "Zul'jarra به توان جنگی‌ات پی برد.\nخوب است.\nسودمندی‌مان را ادامه دهیم. اگر حالا ما را از سرزمینشان بیرون کنند، هیچ راهی برای پایش Twilight's Blade نداریم تا وقتی که مثل سیل از دروازه‌ها به Eversong بریزند." }
WoWFQ[87254] = { t = "پاک‌سازی نفرین", d = "جنگ‌سالار Akutu هر لحظه ممکن است بمیرد، و تو کبد pango نیاورده‌ای؟ به!\nهر روز فریاد می‌زنم که Kulzi بگوید چطور درمانش کنم. می‌گویم: «وادارم می‌کنی از آیین کبد ممنوعه استفاده کنم!» اما loa هیچ نمی‌گوید.\n<Loa Speaker Sij'ta's eyes seem angry but also afraid.>\nاگر نمی‌گوید مشکل چیست، ناچار از آیین کبد pango استفاده می‌کنیم. می‌گویند آیینی نیرومند اما ممنوع است.\nبزرگ‌ترین کبد pango‌ای که پیدا می‌کنی بیاور. وقتی برای تلف‌کردن نیست.", o = { "Large Pango Liver", "کبد را به جنگ‌سالار Akutu بده" }, p = "آیین کبد هیچ کار نکرد؟", c = "به! این loa...\n<Loa Speaker Sij'ta spits on the ground.>\nحتی آیین ممنوعه هم Akutu را شفا نمی‌دهد؟ این چه نفرینی است؟" }
WoWFQ[87256] = { t = "داروی جایگزین", d = "نمی‌توانم کنار جنگ‌سالار بمانم را رها کنم. سوگند خورده‌ام به خود Zul'jin که جنگ‌سالاران Amani را به هر قیمتی نجات دهم. اگر بروم، حتماً می‌میرد. از مرگ هم سردتر است! اگر حرکت نمی‌کرد و حرف نمی‌زد، سوگند می‌خورد که مرده است.\nچیزهایی هست که بدون تشخیص loa می‌شود کرد. شاخه‌های bloodclot را که زیر نیایشگاه می‌رویند برایم بیاور. برای آیین‌های شفایی که هنوز می‌توانیم انجام دهیم خیلی مهم‌اند.\nبرایم یک تپه ازشان جمع کن.", o = { "Bloodclot Branch" }, p = "باید تند و تیز باشند تا کار کنند.", c = "با این تعداد، می‌توانیم جادومان را به کل دستهٔ جنگی هم برسانیم!" }
WoWFQ[87267] = { t = "خواسته‌های بی‌پاسخ", d = "خوب، شاخه‌ها را داریم. استفاده‌شان می‌کنیم! بالای سر ما محراب‌هایی است که زخمی‌ها را برای شفا نزد Kulzi می‌بریم...\n<Sij'ta looks very disoriented.>\nصبر کن. این را که قبلاً انجام دادم. Akutu را بالا بردم و روی یکی از محراب‌ها خواباندم. همان‌جا دستم را گرفت. وادارم کرد سوگند یاد کنم که...\nچه؟ چرا یادم نمی‌آید؟\nتو — تو برای دلیلی این‌جایی. برو و جواب پیدا کن. اگر loa پیدا شد، به‌اش بگو باید این را درست کند — وگرنه!", o = { "بخور بسوزان تا Kulzi احضار شود", "با Kulzi صحبت کن", "Shattered Staff" }, p = "Kulzi نمی‌تواند به ما بی‌اعتنا بماند!", c = "این چیزی است که برایم آورده‌ای؟\nیک عصای شکسته؟" }
WoWFQ[87268] = { t = "توبهٔ لازم", d = "این عصا را به یاد دارم. و آن روز را.\nپس ما... مرده‌ایم.\n<Sij'ta seems to take in the realization with a sort of relief.>\nAkutu بعد از نبردی در شهر لب مرگ بود. زخم‌های جدی داشت. Kulzi گفت نمی‌تواند درمانشان کند. Akutu نپذیرفت. خواست من عصا را — عصای hexlord را — روی Kulzi به کار ببرم تا وادارش کنم شفا دهد.\nو بعد... فکر کنم شکستم.\nاین عصا را به روح‌های دیگر این‌جا نشان بده. شاید از خاطراتشان بفهمیم چه گذشت.", o = { "به Forgetful Ghost یادآوری شد" }, p = "عصا را به‌شان نشان بده. ببین چه یادشان می‌آید.", c = "کاش می‌دانستم چرا عصا را شکستم.\nفکر کنم وقتش است که جنگ‌سالار هم مثل ما رو‌به‌روی خاطراتش بشود.\nوگرنه برای همیشه در این نفرین گیر می‌افتیم. باید یادمان بیاید، حتی اگر نخواهیم." }
WoWFQ[87317] = { t = "انکارِ منتفی", d = "خب، عصا را من شکستم. و همه مردیم.\nشاید این اشتباه من است. بعضی وقت‌ها اعتراف به اشتباه خیلی سخت است. و بعد اشتباه‌های بیشتری کردیم. تا این‌جا آمده‌ایم دیگر.\nوقتی با بقیه حرف می‌زدی، تلاش کردم به Akutu برسانم که ما مرده‌ایم. اما گوش نمی‌کند. فقط دیگران را مقصر می‌داند. شاید من هم لایقم.\nعصا را به جنگ‌سالار Akutu نشان بده. بعد او را نزد Kulzi ببر. باید تلاش کنیم با loa حرف بزنیم.\nقطعه‌های این پازل دارند سر جایشان می‌نشینند.", o = { "عصا به جنگ‌سالار Akutu نشان داده شد", "جنگ‌سالار Akutu را پیدا کن", "عصا را به Sij'ta بده" }, p = "چرا کمکم نمی‌کنی؟!", c = "این چه مسخرگی‌ای است؟ گویندهٔ loا می‌تواند برود جلو؟\nهمه‌اش تقصیر او بود!" }
WoWFQ[88986] = { t = "کور کردن راهزن‌ها", d = "این الف پیدا شد این‌جا، دنبال انتقام، فکر می‌کرد ما برای مرگ خواهرش مقصریم.\nاما به‌جای کشتنش، می‌خواهم این پسر را سر جایش بنشانم.\nAmani‌ها چه کاری با یک مزرعه داشتند؟\nنمی‌فهمد که Twilight's Blade از دو طرف مرز Zul'Aman حمله می‌کند!\nتقصیر بچه‌ای نیست. نمی‌داند Twilight's Blade می‌تواند با قدرت‌های تهی‌شان خودشان را پنهان کنند.\nچند تراشهٔ lightwood بردار. روی Twilight's Blade‌هایی که پنهان‌اند بریز. به‌اش نشان بده دشمن واقعی کی است!", o = { "استفاده از Lightwood Splinter روی فرقه‌گرایان Twilight's Blade", "فرقه‌گرایان Twilight's Blade کشته‌شده" }, p = "همان پسر آمد این‌جا تا از اولین ترولی‌هایی که دید انتقام بگیرد.\nبند پاهایش را محکم نگه دار. کمک می‌کند عواقب بی‌فکری بچگانه‌اش را بفهمد.", c = "پسر گیج به‌نظر می‌رسد.\nخوب. شاید دارد فکر می‌کند." }
WoWFQ[88987] = { t = "خرابکاری بازیافته", d = "Rakani وقتی پسر توی اردوگاه کوبید زیاده‌روی کرد، اما همهٔ ما عصبی بودیم.\nTwilight's Blade از قبل قاچاق‌شده بود داخل اردوگاه و خرابکاری کرد.\nاز قبل هم جواب‌گویی به تقاضای سلاح سخت بود. و قوم ما برای دفاع از خودش به سلاح نیاز دارد!\nاگر سلاح‌های شکسته را پس بگیریم، شاید جبران کنیم.\nهمین‌که باشان درگیری، ببین می‌توانی سلاح‌های‌مان را پس بگیری — هر وضعیتی هم که داشته باشند.", o = { "Stolen Equipment (Zul'Aman)" }, p = "آشوبی که آن الف به راه انداخت هیچ است کنار آنچه هر روز با آن درگیریم.\nباید محتاط‌تر باشیم؛ Twilight's Blade دارد در هر حرکتمان خرابکاری می‌کند.", c = "ممنون. این لوازم بازیافته کمک می‌کند کارمان را سر جایش برگردانیم.\nبا اینکه هنوز آن الف همین‌جا گرد و خاک می‌کند..." }
WoWFQ[88988] = { t = "شاگرد استادکار", d = "به‌نظر می‌رسد پسر فهمیده در این دنیا چیزهای بیشتری از مزرعهٔ خانوادگی و ترول‌های مهیب Zul'Aman هست.\nاما هنوز باش کار ندارم. باید سخت‌کوشی هم یاد بگیرد. این پسر باید جبران آشوبی که راه انداخت و کاری که از دست رفت را بکند.\nفرصت یادگیری‌ای می‌شود — برای هر دوی‌تان.\nتو قرار است برای ما چیزی بسازی.\nحواست جمع باشد. یک حرکت اشتباه lightwood را خراب می‌کند. با خرابکاری‌های Twilight's Blade در تجهیزاتمان، منابعمان خیلی محدود شده است.", o = { "Lightwood Chunk", "Lightwood Chunk سنباده خورد", "تیغه به Lightwood بسته شد", "Lightwood Javelin روغن‌کاری شد" }, p = "کار با lightwood سخت است، حتی برای چوب‌کارهای باتجربه.\nصبور باش. دقیق باش. و هر چه می‌گویم بکن.", c = "هوم. بد نیست. برای یک تازه‌کار." }
WoWFQ[88989] = { t = "یکی دیگر روی اره می‌رود", d = "آن پسر یک احمق است.\nاما احمقی با جرات.\nوقتش است سلاحی را که ساختی محک بزنیم.\nاو می‌خواهد برود سراغ فرمانده‌شان. خیلی از استادکارهای من را کشته، اما انتقام نمی‌ارزد جان او یا کسی دیگر را.\nقبل از اینکه خودش را بکشد برو دنبالش.\nهمهٔ این زحمت را به‌خاطر او نکشیدم که همین حالا بمیرد، نه؟", o = { "Lightwood Javelin", "استفاده از Lightwood Javelin روی Covert Commander Tofir", "Covert Commander Tofir کشته‌شده" }, p = "همان فرمانده چند نفر از خودی‌های ما را کشت.\nبه احتمال زیاد سربازانش خواهر آن پسر را کشتند.\nهرچند کشتنش کار ساختن سلاح و رساندنشان به Amani'Zar را راحت‌تر می‌کند، جان آن پسر نمی‌ارزد.", c = "جان آن پسر را نجات دادی. و شاید حالا قبل از اینکه ناگهان تصمیمی بگیرد که جانش را بگیرد، کمی فکر کند.\nو برداشتن سر این حلقهٔ خرابکاری به ما فرصت می‌دهد همهٔ سلاح‌هایی که لازم داریم را بسازیم.\nکارها همیشه به خیر می‌گذرند، نه؟ حتی برای تو.\nیک چیز کوچکی که من و گروه می‌خواهیم به تو بدهیم." }
WoWFQ[89230] = { t = "عاشق، نه جنگاور", d = "سالخوردگان دارند جشنی برای شکرگزاری به loaها می‌گیرند. می‌خواهم از Namaji بخواهم همراه‌ام برود اما....\nرسم است خواستگار هدیه‌ای بدهد که هنر جنگاوریش را ثابت کند. اما من جنگاور ضعیفی‌ام و بقیه به‌خاطرش مسخره‌ام می‌کنند.\n<Kagara hangs his head dejectedly.>\nشاید تو بتوانی کمکم کنی؟ می‌دانم Namaji همیشه گردن‌آویزی از دندان threshadon می‌خواست. gnarldin‌ها می‌سازندشان، اما فقط قوی‌ترین‌ها یکی دارند.\nمی‌توانی یکی پیدا کنی و به نام من به‌اش بدهی؟", o = { "Threshadon Tooth Necklace", "در دهکدهٔ Amani'Zar با Namaji دیدار کن." }, p = "چیزی لازم داشتید؟", c = "این از طرف Kagara است؟ همیشه یکی از این‌ها را می‌خواستم!\nخوشحال می‌شوم با او به جشن بروم. اول کارم را همین‌جا تمام می‌کنم، بعد خودم می‌روم خبرش کنم.\nممنون که رساندی‌اش!" }
WoWFQ[89231] = { t = "جنگاور، نه عاشق", d = "به جشن loa می‌روی؟ توقع است ترول‌های جوان مثل من از کسی که دوستش دارند دعوت کنند. و هدیه‌ای بدهند تا شایستگی‌شان را نشان دهند.\nمن می‌خواهم با Namaji بروم. جنگاور قهاری‌ام، اما مطمئنم خیلی جنگاور دیگر هم می‌خواهند با او بروند!\nآن‌ها به‌اش غنیمت و جایزه می‌دهند. اما من فرق می‌کنم.\nبه‌نظرم تاج‌سری خوشش می‌آید، اما سر در نمی‌آورم چطور می‌سازند‌ش. می‌توانی برای من یک تاج پر بسازی و به‌اش بدهی؟\nپرها را در Akil'zon's Reach پیدا می‌کنی.", o = { "Eagle Feather (Zul'Aman)", "Amani Headdress", "در دهکدهٔ Amani'Zar با Namaji دیدار کن." }, p = "هدیهٔ دیگری؟", c = "چه تاج‌سر قشنگی! از طرف Zak'kash؟ آه...\n<Namaji looks troubled.>\nهم Zak'kash هم Kagara می‌خواهند با من به جشن بروند. چه کار کنم؟" }
WoWFQ[89233] = { t = "مثلث عشق", d = "به‌نظر یک مشکل داریم: هم Kagara هم Zak'kash می‌خواهند با من به جشن بیایند! کدام را انتخاب کنم؟\nهر دوی‌شان را دوست دارم. لطفاً <name>، تو باید کمکم کنی! نظرت چیست؟", o = { "به Namaji در تصمیم‌گرفتن کمک کن" }, p = "هر دو انتخاب‌های خوبی‌اند...", c = "ممنون که کمکم کردی. Kagara، Zak'kash... امیدوارم بعد از این ماجرا هنوز دوست بمانیم.\n<Namaji furrows her brow but then smiles.>\nبهتر است بروم به همراه جشنی‌ام خبر بدهم! باز هم ممنون." }
WoWFQ[89334] = { t = "پیش‌دستی در مسئله", d = "loa یعنی Akil'zon را نمی‌شناسم، اما نمی‌تواند خوشش بیاید که gnarldin‌ها به نیایشگاه‌های hash'ey اهانت می‌کنند و از عقاب‌های خویشاوندش غذا می‌سازند.\nباید بفهمند این‌جا جای مقدسی است و از حضورشان در این‌جا خوشمان نمی‌آید.\nشاید Akil'zon را نشناسم، اما غول‌ها را می‌شناسم. هیچ چیز را نمی‌فهمند جز قدرت — زبان Zul'Aman.\nمحکم‌ترین پیامی که می‌شود فرستاد این است که سر جنگاورترینشان را ببریم.", o = { "سر Brulagh the Crusher", "سر Cragward Gaahl", "سر Pulverizer Helthra", "در پای معبد Akil'zon با Zul'jarra دیدار کن." }, p = "سرهای‌شان را ببر. روشش چقدر دردناک باشد، بین تو و هر نیرویی که می‌پرستی.", c = "<Zul'jarra takes one of the heads by the hair and admires your handiwork.>\nحالا داریم به زبانشان حرف می‌زنیم. حالا می‌فهمند که Amani قوی‌ترند!\nبعضی‌شان می‌مانند، اما وقتی Twilight's Blade را شکستیم، برای‌شان برمی‌گردیم.\nسرها را نگه دار. فکری برای استفاده‌شان دارم." }
WoWFQ[89503] = { t = "خواهر و برادر غمگین", d = "Iz'ken سال‌ها پیش ما را ترک کرد، <name>. آماده‌کردن‌ها شاید پرتنش باشد، اما دست‌کم تنها نیستیم.\nاول باید هاگ قارچ‌های گریان را جمع کنیم. از خود قارچ‌ها می‌گیری، یا از گرازها.\nباشان بخور آیین می‌سازم.\nمواظب باش، <name> — گرازها وقتی غذایشان را می‌گیریم شاید خوشحال نباشند.", o = { "Weeping Spores" }, p = "می‌گویندش هاگ گریان، چون وقتی می‌سوزد چشمت را می‌گیرد.\nهاگ به جنگجویانمان بهانهٔ خوبی می‌دهد اگر برای اعتراف به احساساتشان نزد آتش، خیلی ترسو باشند.", c = "از تو کمک خواستم بی‌آنکه بگویم مادرم با من و برادرم چطور رفتار می‌کرد. کم دربارهٔ خانواده‌ام حرف می‌زنم. یاد گرفتم نزنم.\nهنوز نمی‌فهمم چرا آن‌طور بود. شاید اتفاقی برایش افتاده بود. چیزی که همهٔ آن درد را می‌ساخت... شاید درد و آشفتگی تنها چیزی بود که خودش هم می‌شناخت.\nاما در قبیله، خیلی‌ها را با خودش همراه کرد — دست‌کم می‌تواند برای آن‌ها مادری بماند." }
WoWFQ[89506] = { t = "پیوندهای محکم", d = "بعد باید زردپی غول‌ها را جمع کنیم. زردپی مطمئن می‌شود آتش بزرگ از هم نمی‌پاشد، و به‌خطرانداختن جان در برابر دشمنی قدرتمند احترامی است به درگذشته.\nمن جنگاور آزموده‌ای‌ام، برای من نگران نباش. اما حواست باشد Iz'ken از غول‌ها آسیب نبیند.", o = { "Resilient Sinew" }, p = "زردپی غول‌های کوهستان مادهٔ ساختمانی محکمی است.\nاما فقط برای همین یک کار استفاده‌اش می‌کنیم، چون گرفتنش خطرناک است و غول‌ها هم آن‌قدر زیاد نیستند.", c = "اول‌ها وقتی Iz'ken رفت، فکر می‌کردم مادرم اهمیتی نمی‌دهد. تا روی بستر مرگ هم یک بار هم اسمی از او نبرد.\nاما وقتی رفت احساس گناه می‌کرد. قهرهای‌اش به من بارِ شرم را حمل می‌کرد، فکر کنم.\nکاش اعتراف می‌کرد، اما می‌دانستم هرگز نمی‌شود.\nقبیله‌مان مادرم را تسلط‌ناپذیر می‌داند... بی‌ترس.\nاما بعضی وقت‌ها همان چیزی که درون است، سخت‌ترین است که رو‌به‌رویش ایستاد." }
WoWFQ[89513] = { t = "هیزم به‌اندازه", d = "بعد، باید هیزم آتش بزرگمان را جمع کنیم. Kan'sha، درخت بزرگ انتهای دره، سال‌ها پیش از یک تیر سرگردان مسموم شد.\nخیلی تنومند است. برای زنده‌ماندن، مرتب شاخه‌هایش را می‌ریزد.\nبه نوعی، Kan'sha به بخشی همیشگی از آیین‌های‌مان بدل شده. چوب محکمش گرم و داغ می‌سوزد — مثل خون Amani.\nبرای آتش بزرگ عالی است.", o = { "Fallen Branch of Kan'sha" }, p = "برای Kan'sha نگران نباش. از نسل‌های زیادی از ترول‌ها عمر کرده، و درویدها می‌گویند خیلی نسل دیگر هم زنده می‌ماند.", c = "Kan'sha دوست قدیمی است، و خیلی شب‌ها وقتی نمی‌توانم بروم خانه، زیر کاج‌هایش استراحت می‌کنم.\nقبیله‌مان به مردم می‌گوید مواظب شاخه‌های افتادنی‌اش باشند، اما هرگز به من نخورد. نه یک زخم، نه یک کبودی از او." }
WoWFQ[89559] = { t = "پرستش بی‌سبب", d = "جلوتر نیایشگاه قدیمی است. دیگر هیچ‌کس نمی‌داند آن‌جا چه می‌پرستیدیم یا چرا، اما جایی بود که مادرم دوستش داشت.\nاگر سنگی از آن را با او روی آتش بگذاریم، برایش افتخاری است.", o = { "Weathered Shrine Piece" }, p = "هر دوی‌مان می‌دانیم نیایشگاه جایی بود که مادرم را خوش می‌آمد.\nنمی‌توانم بگویم آن‌قدر دربارهٔ ما می‌دانست.", c = "بقیهٔ قبیله هنوز مادرم را محترم می‌شمارند و بر مرگش سوگواری می‌کنند.\nاما از وقتی مرد، من بیشتر دلم برای Iz'ken تنگ شده.\nاو برادرم را راند.\nاما... مرگش او را برگرداند. دست‌کم برای همین آیین." }
WoWFQ[89560] = { t = "خداحافظی خاموش", d = "حالا آتش بزرگ را برپا می‌کنیم تا پیکر بسوزد. نابودکردن پیکر یعنی Vilebranch نتواند برای شر از آن استفاده کند و مطمئن می‌شود روح به آرامش می‌رسد.\nهنوز هم قلبم را می‌لرزاند که حالا چقدر ساکت است.\nقبیله باید پایین در Funerary Coast جمع شده باشد.", o = { "Shrine Piece گذاشته‌شده", "زردپی چیده‌شده", "شاخه‌ها گذاشته‌شده", "آتش روشن شد", "ادای احترام کن" }, p = "وقتش است. آماده‌ایم.", c = "ممنون که در این سفر کمکمان کردی، <name>.\nفکر نمی‌کردم Iz'ken بیاید، و او فکر نمی‌کرد جای‌اش باشد.\nفکر کنم حالا من و Iz'ken می‌فهمیم... بدترین حیلهٔ مادرم این بود که ما را مقابل هم بایستاند." }
WoWFQ[89565] = { t = "راه سوگواری", d = "hash'ura، می‌توانم از تو کمک بخواهم؟\nمادرم به‌تازگی درگذشت، و من مسئول برگزاری آیین‌های مرگش هستم. کار زیادی است برای یک نفر.\nبیشترها از خانواده کمک می‌گیرند، اما خانواده‌ای برایم نمانده. می‌توانی کمکم کنی؟", c = "برادر کوچک‌ترم وقتی تازه به سن بلوغ رسیده بودم ما را ترک کرد.\nپیغام فرستاد می‌آید کمک کند اما... خوب از هم جدا نشده بودیم.\nاما این‌جاست. بعد از این‌همه مدت." }
WoWFQ[90481] = { t = "مجوز دارم", d = "این جوان‌های Witherbark می‌گویند نمی‌توانیم این‌جا بمانیم.\nاما ماه‌هاست با یکی از سالخوردگانشان حرف می‌زنم تا مطمئن شویم اجازهٔ برپا‌کردن اردو و کاوش را داریم. حتی رونوشت همهٔ نامه‌ها را دارم!\nمی‌توانی Elder Ren'zen را در دهکدهٔ Witherbark پیدا کنی و نامهٔ تأییدش را به‌اش نشان دهی؟", o = { "Elder Ren'zen پیدا شد" }, p = "Elder Ren'zen توی نامه‌ها خیلی خوش‌برخورد به‌نظر می‌رسید. حالا چرا این‌همه خصومت؟", c = "تأیید کرد که چیزی که فرستاده نامهٔ تأیید بوده؟ خوب است! خوشحالم که تکلیف روشن شد.\nشاید حالا بشود معرفی خوشایندتری به Zul'Aman داشت." }
WoWFQ[90482] = { t = "پیوند آشپزی", d = "این «جستجوگر» کلی سؤال دربارهٔ غذاهایی که می‌خوریم می‌پرسد.\nبه‌نظر می‌رسد این tortollan‌ها دوست دارند غذاهای سمی بخورند. Witherbark‌ها هم همین‌طور. خیلی از غذاهایی که می‌خوریم اگر درست آماده نشوند، ما را می‌کشند.\nبرو معدهٔ Zapapgut Eel و جلبک Blisterskin را جمع کن. می‌خواهم زبان این لاک‌پشت را امتحان کنم.", o = { "Clinging Depthsroot خورده شد", "Zapgut Eel Stomach", "Blisterskin Kelp" }, p = "بعضی زهرها را می‌خوریم تا در برابر خطرهای احتمالی مقاوم شویم.\nبعضی‌شان فقط مزه‌شان خوب است یا هیجان خوبی می‌دهند.", c = "عالی. حالا نوبت آماده‌کردنش است." }
WoWFQ[90483] = { t = "قصهٔ Witherbark", d = "Witherbark‌ها می‌گویند کلی قصه برای گفتن دارند، اما من دو تا شنیدم و هر دو شامل گلاویزشدن بودند!\nلطفاً، می‌توانی از Witherbark‌های همین‌جا قصه بپرسی؟ این استخوان‌های پیرم تحمل یک اجرای دیگر را ندارد!", o = { "قصه‌های Witherbark اجرا شد" }, p = "چه اشکالی دارد قصهٔ ملایمی دربارهٔ به‌خواب‌رفتن در وقت نامناسب؟\nفولکلور tortollan پر از این‌هاست. مگر ترول‌ها نمی‌خوابند؟", c = "فهمیدم. دست‌کم سابقهٔ همهٔ این نبردها را مرتب ثبت می‌کنند. قصه‌گویی‌شان خیلی طاقت‌فرساست!" }
WoWFQ[90484] = { t = "Stegadon گردشگر", d = "وااای، زره‌ات خییییلی خفن است!\n<Trishe stares, slack-jawed.>\nآه، دوستم Steggy را ندیدی؟ این‌جا با من بود، بعد یه‌عالمه حشرهٔ قشنگ و این‌چنین‌ها بود و او رفت دنبالشان، و من آن‌قدر کند بودم که نتوانستم دنبالش بروم.\n<Trishe pouts.>\nقرار بود حواسم به Steggy باشد. من مسئولم! و حالا تو مسئول پیدا‌کردنش هستی، باشه؟", o = { "Hidegorger the Everburning کشته‌شده", "Steggy آرام گرفت" }, p = "دیدی ترول‌ها چقدر بزرگ‌اند؟ Steggy قرار است از ترول‌ها بزرگ‌تر شود، اما هنوز مثل من کوچک است.\nSteggy باید بخورد تا بزرگ شود. لطفاً پیدایش کن تا غذایش بدهم!", c = "Steggy برگشت! تو واقعاً مسئولی." }
WoWFQ[90485] = { t = "یادگارهای ثانویه", d = "این‌جا جای ایده‌آلی برای پیدا‌کردن یادگارهاست. جست‌وجو در آوار کف آن دریاچه می‌تواند گنج‌های زیادی آشکار کند.\nاگر وقت داری، خودت هم می‌توانی بگردی. هر چه پیدا کردی برایم بیاور تا ببینیم ارزشمند است یا نه.", o = { "Lost Amani Bolt", "Lost Amani Oar", "Lost Amani Trinket", "آوار پاک‌سازی شد", "Old Amani Pot" }, p = "تا حالا چیز هیجان‌انگیزی پیدا نکردی؟", c = "وای وای، چه یافتهٔ جالبی!\nاز یک دیگ قدیمی خیلی چیز می‌شود یاد گرفت: Amani‌های باستانی چطور غذا آماده می‌کردند، چه غذاهایی می‌خوردند، و در یک وعدهٔ غذا چه چیزی برای‌شان از همه مهم‌تر بود.\nمن سراغ تحلیلش می‌روم. آن چیزهای دیگر را می‌توانی بگذاری یک‌سو. خیلی جوان‌تر از این زیبایند." }
WoWFQ[90486] = { t = "خوراکی‌های خطرناک", d = "یک ترول Witherbark می‌تواند هر یک از این مواد را خام بخورد و زنده بماند، اما کمک لازم دارد.\nهمین‌که با هم بریزیم، کشنده می‌شود. داریمشان را در یک غذا می‌پزیم.\nنگران نباش. نشانت می‌دهم چطور آن‌قدر زهرش را بگیری که هم مزه بدهد هم اثر فلج‌کننده داشته باشد.", o = { "Prepared Zapgut Eel فشرده شد", "روی Blisterskin Kelp بپر", "Prepared Saltleaf Boar برش خورد", "Blistereel Boar Skewer پخته شد" }, p = "به‌نظرت چه مزه‌ای می‌دهد؟ Amaxi می‌گوید خیلی تند و دلفریب است و می‌تواند یک stegodon را بکشد!", c = "فکر کنم حالا نوبت امتحان‌کردنش است. درسته، <name>؟" }
WoWFQ[90568] = { t = "دوستی غیرمنتظره", d = "این دیگ قدیمی Witherbark که پیدا کردی خیلی جالب است.\nسری نکته‌ها دربارهٔ ساخت و کاربردش یادداشت کرده‌ام، اما حالا وقتش است با Elder Ren'zen حرف بزنیم. دیگ باید به‌اش برگردانده شود. و او می‌تواند جای‌خالی‌های قصهٔ دیگ را پر کند!\nدر دهکده با او حرف بزنیم.", c = "Seeker Crikkash می‌گوید منتظر رسیدن تو بود تا چیزی را که پیدا کرده به من نشان دهد." }
WoWFQ[90772] = { t = "شعله‌ها بلندتر می‌شوند", d = "زغال... حالا سفیدداغ است. و حس می‌کنم چیزی توی آن است؟\nBrek گفت این آخرین آزمون است. اما Jan'alai این‌جا نیست.\nحالا چه کار کنیم؟\n<Zul'jarra looks at Brek and scowls.>\nبا Brek حرف بزن ببین چیزی برای گفتن دارد که ما بفهمیم یا نه.", o = { "با گویندهٔ loa، Brek، صحبت کن" }, p = "اگر نتوانم با Jan'alai ارتباط بگیرم، راه hash'ey همین‌جا در معبد متوقف می‌شود.", c = "انجامش دادیم، hash'ura.\nJan'alai دوباره زاده شد! و برکتش را داریم.\n<Zul'jarra closes her eyes and briefly enjoys the feeling of the flame against her face.>" }
WoWFQ[91001] = { t = "راه را باز کن", d = "با از‌کار‌انداختن جادوی‌شان و شکستن صفشان، Twilight's Blade در حال از‌دست‌دادن زمین است.\nباید از پشت‌سرشان استفاده کنیم.\nمن هجوم را از میان دره به Conquerer's Sanctum آن‌سو هدایت می‌کنم. Mor'duun آن‌جاست، و دارد کالبد ترسویش را از نیزه‌ها و تبرهای ما دور نگه می‌دارد.\nخیلی طول نمی‌کشد که آن‌جا امن نباشد.", c = "Mor'duun شاید حالا بخندد، گیر افتاده در Sanctum.\nاما خندهٔ آخر از آن ماست." }
