WoWFQ[91062] = { t = "پل‌های شکسته", d = "قبل از اینکه همراه Liadrin به Silvermoon برگردی، hash'ura، یک درخواست آخر از تو دارم.\nZul'jan را پیدا کن. از وقتی به Amani'Zar برگشته کسی او را ندیده است.\nدر راه برگشت، دربارهٔ بردن سربازها به Broken Throne برخلاف دستور من با او درگیری.\nآدم‌هایی مردند که نباید می‌مردند. از او پرسیدم چیزی از این نمی‌فهمد؟\nاستدلال نکرد. خالی بود. کالبدش آن‌جا بود، اما ذهنش؟\nبعضی وقت‌ها در صدای موج دریا آرامش می‌گیرد.\nشاید روی Skybridge پیدایش کنی.", o = { "کمی بمان و گوش کن", "از Zul'jan خبر بگیر" }, c = "خوشحالم پیدایت کردم. Zul'jarra خبر داد که دنبال Zul'jan در این ناحیه می‌گردی، اما این سرزمین هنوز برای من خیلی ناآشناست.\nاگر پیدایش کرده‌ای و از جشن سیر شده‌ای، باید به Silvermoon برگردیم." }
WoWFQ[91069] = { t = "انتقام برای Tolbani", d = "من و Tolbani قایق را پر کرده بودیم از دارو، فولاد و آذوقه تا بالا دست رود به اردوی پیش‌رو برسانیم.\nقرار بود حرکتی بی‌سروصدا باشد: نه دردسری، نه چشمی که ببیندمان.\nاما در آب‌های کم‌عمق، murloc‌ها از میان نی‌ها ریختند بیرون، همه کف و دندان. محکم زدند — آن‌قدر تند که نتوانستیم درست دفاع کنیم. واژگون شدیم و محموله را از دست دادیم. خودم به‌زور به ساحل رسیدم.\nTolbani نتوانست. پیکر تیرخورده‌اش را کشان‌کشان این‌جا آوردم.\nmurloc‌ها باید حساب این کار را پس بدهند.", o = { "murloc کشته‌شده" }, p = "خون این جانوران بی‌عقل را بریز. جور کشتن Tolbani را بکشند.", c = "می‌شنوی؟\nسکوت است.\nاین صدای انتقام است." }
WoWFQ[91070] = { t = "پس‌گرفتن اموال", d = "وقتی با پای زخمی از رود برمی‌گشتم، چند murloc را دیدم که کیف‌های آذوقه‌مان را از گل می‌کشیدند. هم‌دست هم نبودند. مدام به هم گاز می‌گرفتند و می‌خواستند بهترین قطعه‌ها را برای خودشان بربایند.\nیکی‌شان یک کیف کامل را پشت درخت افتاده‌ای قایم کرد. یکی دیگر چیزی را زیر تلی از سنگ دفن کرد. این هیولاهای حریص فکر می‌کنند می‌توانند از ما بدزدند و بی‌سروصدا بروند.", o = { "Food Provisions جمع شد" }, p = "بله، <class>؟", c = "خوب است. همین دیگر، همه‌اش." }
WoWFQ[91071] = { t = "بلای Atal'Abasi", d = "قایقمان خودمان به گل ننشست.\nداشتیم با murloc‌ها می‌جنگیدیم که یک‌دفعه در هوا بودیم.\nهمین‌جا بود که دیدمش — یکی که از بقیه نبود. بزرگ‌تر. قوی‌تر. وقتی حمله کرد، بقیه murloc‌ها پراکنده شدند.\nقایقمان را برداشت، انگار هیچ وزنی نداشت، و روی سنگ‌ها پرتش کرد. از murloc هرگز چنین چیزی ندیده بودم.\nاگر آن murloc ماهیچه‌ای بگذارد روی رود، مدام آدم و آذوقه از دست می‌دهیم.", o = { "Mrruk the Musclefin کشته‌شده" }, p = "رود خطرناک است. باید پسش بگیریم.", c = "دیدم کوچک‌ها از ترس فرار کردند. خوب بود، <class>." }
WoWFQ[91206] = { t = "آشفتگی loa", d = "حالا که داریم تلاش می‌کنیم با همهٔ loaها ارتباط بگیریم، ذهنم می‌رود سمت Kulzi، loaی درمان — و دیوانگی‌ای که دور نیایشگاهش پیچیده.\nگویندهٔ loa‌اش، Sij'ta، دوست خوبی بود. دسته‌های جنگی زیادی را از زخم شفا داد. اما اتفاقی در نیایشگاه Kulzi افتاد و حالا پر از روح‌های خشمگین است.\nبه هر کسی که بخواهد نزدیک شود حمله می‌کنند، و loa هم خاموش است.\nشاید تو بالاخره بتوانی به loa دسترسی پیدا کنی و گوینده‌اش را پیدا کنی!", c = "یعنی چی، دارو نداری؟ خیلی وقت گفتم برو بیاور!\nباید به او کمک کنیم... حتی اگر loa نخواهد!" }
