WoWFQ[91398] = { t = "کتاب‌های ترس", d = "دانش یعنی قدرت، و اوگرها دارد می‌خوانند.\nکتاب‌هایشان را برایم بیاور تا دیگر این‌قدر قدرت پیدا نکنند.", o = { "Ogre Tome of Dark Magic" }, p = "کتاب‌ها را بیار.", c = "ممنون. این‌ها مستقیم می‌روند توی آتش." }
WoWFQ[91399] = { t = "خاکسترهای تهی", d = "عنصری‌های تهی فقط یک کاربرد دارند.\nغباری که می‌ریزند برای آیین‌های جادوی سایه به کار می‌آید.\nبرای قبیله‌مان ازشان جمع کن.", o = { "Void Ashes" }, p = "نگران نباش، قرن‌هاست این آیین‌ها را برگزار می‌کنیم.", c = "شکارچیانمان از این پودر استفاده‌های خوبی می‌کنند. ممنون." }
WoWFQ[91400] = { t = "تبرهای افتادگان", d = "بعد از نبرد، خیلی از سلاح‌های‌مان را جا گذاشتیم.\nلطفاً برو جمعشان کن که Twilight's Blade به‌شان نرسد.", o = { "Forgotten Amani Axe" }, p = "دنبال تیزترین تبرها بگرد. آن‌ها مال ما هستند.", c = "ممنون که جمعشان کردی. حالا دشمنمان از صنعتگری خوب Amani بهره‌ای نمی‌برد." }
WoWFQ[91401] = { t = "مرده تا غروب", d = "فرقه‌گرایان Twilight's Blade جرات کرده‌اند بیایند معبدمان را پس بگیرند. نوکرهای‌شان را بکش و استخوان رانشان را برایم بیاور.", o = { "Cultist Femur" }, p = "چرا استخوان ران؟ به تو ربطی ندارد.", c = "برای استخوان‌ها نقشه دارم. ممنون." }
WoWFQ[91402] = { t = "Ultradon مرگبار مفرط", d = "دیدم بعضی از عنصری‌های تهی وسط میدان داشتند آیین مشکوکی می‌گرفتند. به‌نظر می‌رسید داشتند موجوداتی از تهی احضار می‌کردند.\nمواظب باش هر چه احضار شد، حسابش برسد.", o = { "Eminent Ultradon کشته‌شده" }, p = "اگر بگذارند تهی را بیاورند این‌جا، در دردسر بزرگی می‌افتیم.", c = "تا حالا از این‌ها ندیده بودم و امیدوارم دیگر نبینم. خوب انجام شد." }
WoWFQ[91403] = { t = "به‌احتمال زیاد فلج‌کننده", d = "Halazzi می‌گوید Vilebranch‌ها زهر تازه‌ای ساخته‌اند که پار... پارالیز می‌کند — یعنی قربانی دیگر نمی‌تواند حرکت کند — تا بکشان‌ش قربانی‌گاه. می‌گوید زهر قورباغه است.\nگفتم این که معنی ندارد. قورباغه سمی است، دیگر؟ Halazzi گفت قورباغه‌ها معمولاً سمی‌اند نه زهرآلود. اما این‌ها تیغ‌های شاخی تیز دارند، پس شاید زهرآلود باشند! نمی‌دانستم قورباغه زهرآلود باشد، تو می‌دانستی؟\nبریم ببینیم این‌ها زهرآلودند یا نه — آن وقت Witherbark می‌تواند پادزهر بسازد!", o = { "Venomous Horn" }, p = "Halazzi می‌گوید زهرآلود یعنی وقتی گاز می‌گیرد یا خار می‌زند، و سمی یعنی وقتی تو گازش می‌گیری یا می‌خورش! جالب نیست؟", c = "ببین همهٔ نمونه‌هایی که پیدا کردی. رئیس قبیله مطمئناً می‌داند چه کسی می‌تواند برای هر دو پادزهر بسازد." }
WoWFQ[91404] = { t = "زهر پلید تمام‌عیار", d = "Vilebranch‌ها دارند چیزهای بدتری دم می‌کنند. باید بروی سر منبع و کارشان را یک‌سره کنی!\nHalazzi بوی جای درست‌کردن زهرشان را جایی در جنوب‌شرقی به مشامش خورده، و فکر می‌کند بیشتر از زهر قورباغه در کار است.\n...آه، Halazzi همچنین گفت یک جور دندان بزرگ بیاور. اما قورباغه که دندان ندارد. خب، به‌هرحال پیدایش کن!", o = { "Venomhexxer Raxxis کشته‌شده", "Ritual Fang" }, p = "دنبال دندان بزرگ نرفتی؟", c = "هی، این دندان عنکبوست. باید عنکبوت هیولا‌یی بوده باشد!" }
WoWFQ[91405] = { t = "اعتبارسنجی زهر", d = "یعنی در این آمیزه‌ها هم زهر قورباغه هست هم زهر عنکبوت. Halazzi می‌گوید حس می‌کند کسی با آن دندان از Shadra طلب یاری کرده. اگر دندانش این‌قدر بزرگ است، عنکبوتش هم باید هیولایی باشد!\nHalazzi خوشش نمی‌آید که Vilebranch‌ها آن را داشتند. معلوم است. ناراحت است. گوش‌هایش می‌خوابد، مثل بال‌های بادبادک.\nپس باید کمک کنیم. نمونه‌ها و دندان را ببر پیش رئیس قبیلهٔ Witherbark. ما Witherbark‌ها کیمیاگر داریم که هم برای عنکبوت هم برای قورباغه پادزهر دم می‌کنند.", o = { "با رئیس قبیله Vun'zarah صحبت کن", "با Mixer Jamanga صحبت کن", "Daki را نزد Mixer Jamanga بفرست" }, c = "یعنی Vilebranch‌ها دارند با Shadra کار می‌کنند؟\nمگر می‌شود عنکبوت‌ها علیه Witherbark کار کنند؟ این دیگر معنی ندارد." }
WoWFQ[91406] = { t = "دور از Hinterlands", d = "من یک Torntusk از قبیلهٔ Revantusk هستم، و به‌خاطر تاریخمان با Witherbark در Hinterlands به‌شان بی‌اعتمادم. خانواده‌ام به‌خاطر آن‌ها به این‌جا کوچ کرد.\nWitherbark‌های این‌جا در Zul'Aman احترام ما را نگه می‌دارند، اما Witherbark‌هایی که در Hinterlands به یاد دارم، برای قدرت متحدانشان را می‌کشتند و خنجر می‌زدند.\nآن‌ها loaی عنکبوت، یعنی Shadra را می‌پرستیدند.\nوقتی معبد Witherbark در Hinterlands، یعنی Shadra'Alor، فروریخت، Witherbark‌ها باید جایی گریخته باشند. بگرد دنبال نشانه‌هایی از Witherbarkهای Hinterlands و از Shadra.", o = { "نشانه‌های Hinterlands پیدا شد" }, p = "احتمالاً پرستش Shadra را هم با خودشان آوردند.", c = "همهٔ جاهایی که گفتند چسبیده به Shadra'Alor بودند! حتماً Shadra را می‌پرستیدند.\nنمی‌شود به‌شان اعتماد کرد. مثل زهرهایی هستند که به کار می‌برند. بقیهٔ قبیله را علیه Revantusk مسموم می‌کنند — علیه همهٔ ما!" }
WoWFQ[91407] = { t = "چشم loa", d = "در Hinterlands دوستانم را از دست دادم؛ از زهرهایی که از عنکبوت‌های Shadra می‌ساختند. باید بدانم که Shadra همین دور و برها کمین نکرده و ذهن این Witherbark‌ها را می‌پیچاند. با Witherbark‌های Shadraپرست در اطراف، هیچ Revantusk‌ای در Zul'Aman امن نیست!\nشاید پارانویا به‌نظر بیایم، اما دلیل دارم. و تو گوش Halazzi را داری. می‌توانی از او بخواهی هر عنکبوت پنهانی را برایت آشکار کند، نه؟ می‌دانم آن گوش‌های بلند صدای خزیدنشان را می‌شنوند!\nپشت سر من نیایشگاهی است. جلوی آن بایست و ببین برکت‌ای به تو می‌بخشد یا نه.", o = { "یاری Halazzi درخواست شد", "عنکبوت‌ها ترساندند و راندند" }, p = "Halazzi کمک کرد؟ هر چیزی را می‌شنود، اما آنچه در سایه پنهان است را هم می‌بیند.", c = "عنکبوت‌ها فرار کردند؟ فکر می‌کردم بیشتر جنگ کنند. و گفتی کوچک بودند؟ هوم.\nخب، مهم نیست. Halazzi ما را به این شکار انداخت. حالا باید ببریمش تا آخر." }
WoWFQ[91408] = { t = "در جست‌وجوی Shadra", d = "به‌زودی این دردسر Witherbark و Vilebranch را حل می‌کنیم. اما loa یعنی Shadra و نقشه‌هایش اولویت اول ماست.\nدیدم عنکبوت‌ها چطور از ترس از تو فرار کردند، و چیزی ذهنم را گرفت. عنکبوت‌ها فقط از وحشت نمی‌دوند — دارند به جایی می‌روند... جایی که احساس امنیت می‌کنند، و حالا حتی من هم می‌توانم ببینمشون.\nدیگر قایم نمی‌شوند. دارند می‌گریزند! شکارمان ادامه دارد.\nبزن بریم دنبالشان.", o = { "عنکبوت‌ها را دنبال کن.", "با Mixer Jamanga صحبت کن" }, p = "هر جا این رد برود، ما هم می‌رویم.", c = "بگذار ببینیم چه می‌گوید، اما دستت روی سلاحت باشد." }
WoWFQ[91409] = { t = "رؤیای عنکبوت‌ها", d = "سه یادگار از Shadra هست. من فقط دو تا داشتم. دندان را در دهکده داشتم و چشم را این‌جا پنهان کرده بودم. دندان را یک‌جوری دزدیدند، بعد آمدند برای چشم!\nپوستهٔ Shadra را هرگز نداشتیم — وقتی Shadra'Alor را ترک کردیم گم شد. ممکن است Vilebranch‌ها پوسته را داشته باشند.\nبا دندان و چشم می‌توانیم لحظه‌ای با Shadra حرف بزنیم، حتی اگر یادگار آخر آیینِ احضار را نداشته باشیم.\nبا من بیا. نشانت می‌دهم چطور.", o = { "Fang of Shadra گذاشته‌شده", "Eye of Shadra گذاشته‌شده" }, p = "همین دو یادگار باید برای حرف‌زدن با تجسمی از Shadra کافی باشد.", c = "این همان Shadra‌ای است که در Shadra'Alor به یاد دارم. اگر ما به او کمک کنیم، او هم به ما کمک می‌کند.\nبه وعده‌هایش وفا می‌کند." }
WoWFQ[91410] = { t = "loa مشترک", d = "رئیس قبیلهٔ Witherbark می‌داند که خیلی از ما با پرستش Shadra'Alor از Hinterlands آمدیم، اما فکر می‌کرد Shadra مدت‌هاست مرده است.\nباید خبرش کنیم که Halazzi چطور کمک کرد Shadra را پیدا و بازگردانیم، و از حضور Shadra در آرامگاه Witherbark. باید از این رابطه با Revantusk هم باخبر شود.\nمن فعلاً پیش Shadra می‌مانم، پیام را تو می‌رسانی؟", c = "با Shadra در کنار ما علیه Vilebranch، جنایاتشان را سخت کیفر می‌دهیم." }
WoWFQ[91411] = { t = "Maisara Caverns: در عمق Maisara", d = "Shadra خواسته که قطعهٔ سوم آیین Mixer Jamanga را پس بگیریم: پوستهٔ Shadra را. با آن، شاید بتوانیم او را برگردانیم.\nهم Witherbark هم Revantusk را متحد خودش شناخت. حس رضایتش را روی همهٔ ما حس کردم. باور دارم انتخاب درست همین است.\nHalazzi ما را به این راه انداخت، و هر کداممان نقشی داریم تا ببریمش تا آخر. متحدانت را جمع کن و برو داخل Maisara Caverns! انتظار دارم یکی از رهبرانشان پوسته را نگه دارد. بکشش و پس بگیر.", o = { "Shell of Shadra" }, p = "فکر می‌کنم Shadra به قولش وفا می‌کند.", c = "نمی‌شود تصور کرد این کار راحت بوده. Halazzi حتماً شکار تو را برکت داده است." }
WoWFQ[91412] = { t = "بازگشت ملکهٔ زهر", d = "وقت آن است که Shadra را به جای واقعی‌اش به‌عنوان loaی Witherbark و Revantusk برگردانیم. اول کوچک است، اما یک روز می‌تواند مثل Halazzi و Nalorakk بزرگ شود!\nحتی یک loa کوچک، متحد خوبی علیه زهرهای Vilebranch است. او loaی جاسوس‌هاست و دزدیدن مردم و یادگارهای ما را سد می‌کند.\nپوستهٔ Shadra را وسط اتاق نگه دار، و loa را به سمت خودمان می‌خوانیم!", o = { "آیین Shadra کامل شد", "تخم‌مرغ Shadra باز شد" }, p = "این بیشتر از بازگشت یک loa است — پلی میان قبیله‌هاست.", c = "این سفر بود که... چشممان را باز کرد.\nاگر اولِ کار می‌پرسیدی که با Shadra متحد می‌شویم، ریز می‌خندیدم تو صورتت!" }
WoWFQ[91556] = { t = "شعلهٔ loa", d = "باید باقی ماندهٔ لوازم را پیاده پس ببرم.\nقایق... دیگر به درد نمی‌خورد. بدنه ترک خورده و اسکلتش شکسته. روح دیگری را از روی آب نمی‌برد.\nاما هنوز یک کار آخر برایش می‌ماند.\nمی‌تواند هیزم‌سوز او باشد. می‌سوزانیمش، همراه سلاح‌ها و زره‌ای که پوشیده بود — همه‌چیز را با او.\nانتقام گرفته شد. حالا اجازه می‌دهیم آتش او را به loaها و آرامش برساند.", o = { "Amani Boat بازیابی شد", "آتش بزرگ مراسم برپا شد" }, p = "دیگر نمانده، Tolbani.", c = "امیدوارم روحش را آرام کند. و روح مرا هم." }
