WoWFQ[91630] = { t = "دیدِ دزدیده‌شده", d = "می‌توانم توضیح بدهم، قسم می‌خورم!\nدانشم را از Shadra پنهان کردم چون خیلی‌ها فکر می‌کنند او نیرویی شیطانی است. بانوی ما بی‌رحم است، اما فقط با دشمنانش.\nوقتی Witherbark‌ها Hinterlands را ترک کردند، ناچار معبدمان یعنی Shadra'Alor را رها کردیم. دو تا از یادگارهایش را با خودم آوردم: چشم و دندان.\nVilebranch‌ها دندان را دزدیدند. نزدیک جایی که چشم Shadra را پنهان کرده‌ام، دارد از بچه‌های او زهر می‌گیرند! لطفاً Vilebranch‌هایی را که به آرامگاه تجاوز کرده‌اند بکش. نمی‌توانیم بگذاریم چشم را پیدا کنند.", o = { "Eye of Shadra (Zul'Aman)" }, p = "می‌فهمم چرا زهر می‌خواهند، اما یادگارها فقط برای ارتباط با Shadra هستند. به چه دردشان می‌خورد؟", c = "باید نقشه‌شان این باشد که ما و توان ارتباطمان با Shadra را سست کنند." }
WoWFQ[91747] = { t = "خیلی هم Nalorakk نیست", d = "تو همان بودی که دیدم همراه Zul'jarra وارد معبد Nalorakk شدی؟\nحدس می‌زدم! Zul'jarra با او حرف زد، نه؟\n<Furgh growls in an unsettling way from deep in his throat.>\nاین که معنی ندارد. Voice of Nalorakk جدید می‌گوید Nalorakk با هیچ‌کس جز خودش حرف نمی‌زند.\nبه بعضی از قبیله تزئین داده تا خودشان را به Nalorakk نزدیک‌تر حس کنند. اما حالا قبیله سرشان دعوا می‌کند. ursaها فکر می‌کنند ناعادلانه است که هیچ نمی‌گیرند. اما برگزیدگانشان را چسبیده‌اند.\nباید پیش از آنکه خون بیشتری بریزد، پس بگیریمشان.", o = { "Nalorakk Trinket" }, p = "من نمی‌خواهمشان. می‌اندازیمشان توی آتش.", c = "فکر کنم تزئین‌ها هم آلوده شده بودند.\nخوشحالم که تزئین‌ها از چنگ قبیله‌ام بیرون آمدند." }
WoWFQ[91748] = { t = "خیلی زیاد Twilight", d = "این خرس بزرگ اسمش را گذاشت Voice of Nalorakk و بعضی از قبیله‌مان را «برگزیده» کرد. نمی‌داند، اما دیدم که سنگ‌های آهن‌ربایی درخشان تاریک را در توتم‌های دور دهکده جاسازی کرد تا به برگزیدگانش قدرت بدهد.\nاز آن‌ها قدرت تاریکی می‌تپد. بوی قدرتش می‌زند. شبیه Nalorakk نیست.\nخرس‌های نگهبانمان نزدیکشان بی‌قرار و آشفته می‌شوند. آن‌ها هم بو می‌کشند!\nباید اردو را پاک کنیم. این توتم‌ها را از بین ببر!", o = { "آلودگی پنهان نابود شد" }, c = "نمی‌دانم این خرس قلابی سرش چه می‌پزد.\nاما بهتر است که سنگ‌های آهن‌ربایی‌اش نابود شوند." }
WoWFQ[91749] = { t = "این دیگر درست نیست", d = "باید دلاور باشیم تا جلوی رئیس قبیله را بگیریم. به‌اندازهٔ کافی دلاور نبودیم و خیلی بد شد.\nاگر رئیس قبیله Groffa دارد قبیله را به سمت تاریکی می‌برد، باید جلوی‌اش گرفته شود. فکر کنم تزئین‌هایی در قبیله‌گاهش قایم کرده، خیلی بیشتر از آنچه به قبیله داده. راهش را ببند و ببین چه چیزی پنهان می‌کند!", o = { "Groffa the Guzzler کشته‌شده", "Groffa's Treasures" }, p = "چه چیزی در اردوگاهش احتکار کرده؟", c = "<Furgh licks his chops. They are wet with drool.>\nکیسه حس... وسوسه‌کننده دارد. این را دوست ندارم!\nخوب است که از بقیه دور نگهش داشت، اما برای خودش هم خیلی بد است." }
WoWFQ[91750] = { t = "خطرهای اعتماد", d = "چه ترسناک بود. کاش Furgh از دست نمی‌رفت!\n<Fleeg's fur twitches in fear and worry as he looks Furgh over.>\nFurgh می‌گفت بعد از لمس گنج‌ها، صدای Voice of Nalorakk را شنید که با او حرف می‌زد.\nاما این نمی‌تواند صدای Nalorakk باشد. Nalorakk به تزئین نیاز ندارد!\nگلوی این شرارت را پاره کن که جرات کرده مدعی شود از طرف Nalorakk حرف می‌زند!", o = { "Fake Voice of Nalorakk کشته‌شده" }, p = "<Fleeg howls mournfully.>\nجور کاری که با Furgh کردند را بکشید!", c = "هیولای Twilight's Blade بود!\nامیدوارم حالا که مرده، Furgh و بقیه حالشان خوب شود." }
WoWFQ[91796] = { t = "مأموریت ویژه: دوباره مال ما!", o = { "در Avatarِ loa حلول کن", "Echoها را بکش", "با قابلیت Time Flies سفر کن", "Raid Leader کشته‌شده" } }
WoWFQ[91798] = { t = "ماهیِ روز", d = "دهکده‌مان را Twilight's Blade غارت کرد. باید آذوقه‌مان را جبران کنیم. تو در شکار دستت خوب است؟", o = { "Slippery Snapper" }, c = "بد نیست. این‌ها تازه‌تر به‌نظر می‌رسند از آنچه furbolg‌ها با ما معامله می‌کنند. قبول کن؛ هدیهٔ تشکری Revantusk است." }
WoWFQ[91799] = { t = "خطر یادگارها", d = "Twilight's Blade دهکده‌های‌مان را غارت می‌کند و یادگارهای بی‌قیمتمان را می‌برد. پس بگیرشان!", o = { "Ransacked Heirloom" }, c = "یادگارها و یادمان‌های‌مان را برگرداندی. ممنون، hash'ura — از طرف Revantusk و نیاکانمان." }
