WoWFQ[91803] = { t = "بلای مرداب", d = "murlocها به گاری‌های آذوقه‌مان کمین می‌کنند. بر آن‌ها بتاز و آنچه دزدیده‌اند پس بگیر.", o = { "Stolen Supplies" }, c = "آذوقه را پس گرفتی و گذاشتی فرار کنند! آفرین، <name>." }
WoWFQ[91804] = { t = "ماهی برای آتش", d = "فرزندان آتش غذای تازه می‌خواهند! شنا کن! شیرجه بزن! شکار کن! ماهی‌های فراوانی برای سفره‌مان پیدا کن!", o = { "Lumpy Fish Guts", "Regain Breath from Underwater Airflow" }, c = "فرزندان آتش راضی شدند! مادر شعله‌ها می‌خندد! امروز باران ماهی از راه رسید!" }
WoWFQ[91805] = { t = "شاخ‌وبرگ برای لانه‌ها", d = "خیلی‌ها هنوز از حملهٔ Twilight's Blade در حال بهبودند. دور Shrine of Kulzi گیاه دارویی جمع کن تا برایشان دارو درست کنیم.", o = { "Heartwisp Frond" }, c = "Kulzi را سپاس. ساقه‌ها و ریشه‌هایی که آوردی به همهٔ زخمی‌هایی که زیر دست ما هستند آرامش می‌دهد." }
WoWFQ[91806] = { t = "شکار بزرگ", d = "gnarldinها به گروه‌های شکار ما می‌تازند و از ما می‌دزدند. جوابشان را بده و هر چه توانستی پس بگیر.", o = { "Stolen Game Meat" }, c = "خیلی ممنون. شاید حالا gnarldinها یاد بگیرند از تپه‌های خودشان شکار کنند، نه تپه‌های Witherbark." }
