WoWFQ[91813] = { t = "Spiritpaw", d = "چند furbolg عجیب‌وغریب را تازه از این‌جا راندم.\nدعوایشان شده بود و بعد یکی‌شان دست‌بالا رفته به طرف Lilaju.\nبه آن‌ها حمله کردم و ترسانشان کردم. معمولاً سر هر کسی فریاد می‌زنند و معلوم نبود قصدشان چه بود؟\nاما Lilaju می‌خواهد بداند چه می‌خواستند.\nدیده‌بان‌هایمان دیدند که رودخانه را به طرف شرق، به سمت شمال دریاچه، دنبال کردند. دنبالشان برو. ببین چه می‌خواهند.\nاگر دام بود، بکششان.", c = "ما بدی نمی‌خواستیم. می‌خواستیم دربارهٔ Nalorakk حرف بزنیم.\nخری آمد که می‌گفت به جای loa ما حرف می‌زند، اما حسش غلط بود.\nشاید با کمک تو راهی برای پی بردن به ماجرا پیدا کنیم." }
WoWFQ[91829] = { t = "یکی یکی", d = "هر تک‌تک این فرقه‌ای‌ها خطری برای آدم‌هایی هستند که می‌خواهیم نجاتشان دهیم. برای خود Silvermoon.\nاین متعصبان لعنتی دستشان به خون آلوده است و اجازه نمی‌دهند هیچ‌کس زنده بیرون برود.\nما همین حالا داخل اردوگاه هستیم. بگذار این کار حساب‌شده تمام شود. می‌خواهم حسش کنند.", o = { "Twilight's Blade Cultists کشته‌شده", "Mordrag the Tainted کشته‌شده" }, p = "اگر می‌توانی، کشتارها را بی‌سروصدا نگه دار.", c = "کار تمیزی بود. از آن کارها که دیگر به‌راحتی سراغت نمی‌آیند." }
WoWFQ[91830] = { t = "رهگیری", d = "Twilight's Blade به Tranquillien ضربه زد. همان‌طور که همه مشغول بودند، بدون این‌که کسی بفهمد هر آذوقه و اطلاعاتی که لازم داشتند را با خود بردند.\nوقتش رسیده جوابشان را بدهیم.\nچند چادر را علامت زده‌ام. مراکز فرماندهی، کیف‌های پیغام‌رسان‌ها، دفتر آذوقه زیر جعبهٔ شراب. سفارش‌ها، نقشه‌ها و مسیرها همان‌جاست.\nهر چه می‌توانی بردار.", o = { "Cult Orders" }, p = "همین تکه کاغذهای درست می‌توانند یک جنگ را ببرند. یا شروعش کنند.", c = "خب، این به‌درد می‌خورد. بگذار ببینیم وقتی دنبال اشباح بگردند و جعبه‌هایشان گم باشد، کارشان چقدر رو می‌رود." }
WoWFQ[91831] = { t = "کلید اختیاری است", d = "این‌ها برای پیدا کردن معنا، قدرت یا جایی برای تعلق، به Twilight's Blade پیوستند. برای فرار از ترس و وعده‌ای از قطعیت.\nحالا واقعیتش را می‌بینند--زندانی که خودش را دین جا زده. و می‌خواهند بیرون بیایند.\nبا هم وارد می‌شویم. پیش از آن‌که فرقه بفهمد چه خبر است، بیرونشان بیاور.", o = { "گروه‌های فراری نجات داده‌شده" }, p = "خودت را آماده کن. ممکن است کثیف شود.", c = "این باید همه‌شان باشد." }
WoWFQ[91833] = { t = "عمق‌های گل‌آلود", d = "Vilebranchها هر روز بیشتر در نفرینِ ذهنشان فرو می‌روند. در صورت loa تف می‌کنند و باور دارند بر مرگ مسلط شده‌اند.\nمی‌توانم حدس بزنم این فکر به مذاق یک... شخص خاص خوشش نیاید.\nخویشاوندان ما را برده‌اند و حالا هم شمن‌هایمان را برده‌اند. پیش دیده‌بان من برو و کمکشان کن نقشه‌هایشان را به هم بزنی.\nسرِ هیولا را قطع کن تا تنش بیفتد.", o = { "با دیده‌بان Witherbark در Maisara Deeps دیدار کن." }, c = "وقتت خوب بود، <race>! این نقاب‌های افسون‌شده حسابی قدرتمندند.\nهر چه VunVun برایمان بفرستد، کاربردش را پیدا می‌کنیم." }
WoWFQ[91835] = { t = "بفرست به خونه‌شون", d = "دوست من، این هدیهٔ بزرگی است. Shadra برای کارهای پیشِ‌رو به ما برکت می‌دهد.\nاین Vilebranchها واقعاً به نامشان عمل می‌کنند. روح را از بدن Witherbarkها بیرون می‌کشند و از آن‌ها undead می‌سازند تا برایشان کار کنند.\nباید Witherbarkها را از این پیوندهای نکروتیک آزاد کنیم.\nدوستم هنوز آن‌جاست... امیدوارم. من و Bin'zin دندان عاج‌مان را با هم بلند کردیم. او شمنی قوی شد. دهکده‌مان به او نیاز دارد و برای من مثل برادر است.", o = { "8 زندانی Witherbark را آزاد کن." }, p = "اسیران در امنیت‌اند؟", c = "آره، <name>!\nبا یک ضربه، تعدادمان بیشتر شد و تعدادشان کمتر!\nبهتر است کاری کنیم دیگر هرگز جرئت دست بردن به Witherbark را نداشته باشند." }
WoWFQ[91836] = { t = "احترام به Totem", d = "وقتی Bin'zin را بردند، کاهنه totemهایش را نابود کرد و تکه‌های خردشده را به زیردستانش داد--مثل یک یادگاری نفرت‌انگیز.\nتکه‌ها را پس بگیر؛ حتی اگر ناچار شوی یکی‌یکی. این بی‌احترامی قابل تحمل نیست.", o = { "40 Totem Remnants جمع کن." }, p = "غارت چطور پیش می‌رود؟", c = "در دنیایی پر از وحشت، باید از خوبی‌ای که برای به‌هم‌ریختن کارشان احساس می‌کنیم لذت ببریم.\nاین تکه‌ها به جای خودشان برمی‌گردند.\nخوب بازی‌ات کردی، <name>." }
WoWFQ[91838] = { t = "ذلتِ Vilebranch", d = "این گوی‌های پلید روح آدم‌های ما را درو می‌کنند و انرژی تاریک را به سمت کاهنهٔ چاقو می‌فرستند. دارد حسابی قدرتمند می‌شود.\nگوی‌ها را نابود کن تا آیین مرگش خراب شود. با برکت Shadra، شکست نمی‌خوری.", o = { "5 Vile Orb را نابود کن." }, p = "همهٔ گوی‌ها را پیدا کردی؟", c = "حس می‌کنی؟ آن انرژی مرگی که همه‌جا لکه انداخته بود حالا رقیق شده.\nفقط یک نفس کار می‌برد تا این آیین را برای همیشه تمام کنیم." }
WoWFQ[91839] = { t = "قربانیِ نافرجام", d = "شمن ما به خانه برگشت و Jin'zin از دیدنش ذوق‌زده شده. او همیشه هم آن گربه‌وحشی کوچکِ شاگردش بود.\nروزهای سختی در پیش دارند--از دست دادن Tan'zin ضربهٔ بزرگی است.\nامروز تو او را به خانه آوردی. برو حالش را ببر، $p، قبل از این‌که سر راهت را بگیری.", p = "با او حرف زدی؟", c = "همه‌اش تقصیر خودم بود. Vilebranchها تا همین‌جا به دهکده رسیده بودند... باید بیشتر حواسم بود.\nهمسرم در برابر مرگی که برای من بود پرید.\nیک لحظه خشمگینم، لحظه‌ای بعد احساس گناه می‌کنم و بعد غم فراگیرم می‌کند.\nآخر و عاقبتش، برای Jin صورتی قوی نگه می‌دارم." }
WoWFQ[91840] = { t = "یکی بلند نخواهد شد", d = "الان بهترین فرصت است! قربانی‌ها را همین‌جا تمام می‌کنیم! متوقف کردن انرژی تاریک تسلطش را کم کرده.\nبعد، تو می‌توانی همان کسی باشی که سرش را می‌آورد.\nراستی، و <name>--به هیچ‌کس نگو که من به رئیس می‌گویم Big VunVun. اگر دوباره بشنود، مرا قورباغه می‌کند.", o = { "سرِ کاهنهٔ چاقو Hezzia" }, p = "خوشحالم که حرف‌هایم را این‌قدر جدی گرفتی.", c = "آه! روزم همین الان بهتر شد! Witherbarkها از تو ممنونند، <name>.\nDak'zor نگفت... بی‌خیال. نمی‌خواهم بدانم." }
WoWFQ[91930] = { t = "سرزمین‌های فراوان", d = "loaها دوباره به ما ترول‌های جنگل پیوسته‌اند و زمین با برکتی شکوهمند جواب می‌دهد!\nمی‌خواهی سهمی داشته باشی؟ پس برو شمال و مرا در ورودی Loaknit Den ملاقات کن.\nآن‌جا با فراوانی و نعمتی آشنایت می‌کنم که تا حالا ندیده‌ای...", c = "وقتش رسیده مستقیم از خودِ استاد یاد بگیری." }
WoWFQ[91932] = { t = "بیداری فراوانی", d = "Loa of Abundance همه را می‌پذیرد، و هر کس را که بپذیرد، این امتیاز را می‌دهد که بهترین شیوهٔ خدمت به فراوانی را یاد بگیرد.\nبا چهرهٔ باشکاهش صحبت کن و هم‌پرستش شو.", o = { "با Dundun صحبت کن تا آیین فراوانی آغاز شود", "Abundant Material جمع‌آوری شد", "Loanite Ore استخراج شد", "Kill Credit: Tutorial - Q02 - T0 Approached کشته‌شده", "Passive Abundant Combatant شکست‌خورده", "فراوانی اهدا شد", "Abundant Materials جمع‌آوری شد", "فراوانی اهدا شد", "خودت را برای حذف شدن آماده کن!" }, p = "نترس. من بهترین داورِ هر کار و انتخاب تو هستم.", c = "قابل قبول بود!\nشاید هنوز بتوانی افزوده‌ای باشکوه برای هم‌پرستاران فراوانی باشی." }
WoWFQ[91933] = { t = "افتخار فراوانی", d = "بریم سراغ مرحلهٔ بعدی آموزش: تجارت!\nتصور کن، ثمرهٔ برداشت بی‌پایان را به من، آن وجود باشکوه، پیشنهاد می‌دهی و پاداش‌های فراوانی را که به تو می‌بخشم، به همان اندازه به دست می‌آوری.\nحالا بیا این رؤیای زیبا را عملی کنیم!\nبه تو ذره‌ای از فراوانی خالص می‌بخشم. تو هم در عوض، آن را به هم‌شاگردانت بده تا یکی از کالاهای گران‌بها را بگیری.", o = { "Abundant Beacon را از Chel the Chip بخر." }, p = "چیزهای کمی هست میان فانیان یا خدایان که نتوان از دریچهٔ تجارت به آن نگریست.\nبعضی‌مان فقط... کمتر حاضریم از این حقیقت پنهان‌کاری کنیم.", c = "آه! می‌بینم که تو خودت در فن معامله دستی بلند داری!" }
WoWFQ[91958] = { t = "لانهٔ Nalorakk: بی‌بخشایش", d = "Nalorakk loa جنگ است. آزمونش باید نبرد باشد!\nبرای یک Amani مرگی بزرگ‌تر از مرگ در نبرد با Loa of War نیست. هیجانی بالاتر از جنگیدن با او نیست.\nمگر خون در رگ‌هایت تندتر و محکم‌تر نمی‌تپد، hash'ura؟\n<Zul'jarra lets out a feral howl and laughs.>\nبیا. مرا در Nalorakk's Prowl ملاقات کن تا کنار آتشش بنشینیم و با آخرین آزمونمان روبه‌رو شویم--با هم.", o = { "کمی بمان و گوش کن", "با Zul'jarra صحبت کن تا ورود به follower dungeon آغاز شود", "Nalorakk, Loa of War, در نبرد شکست‌خورده", "بیرون dungeon با Zul'jarra صحبت کن" }, p = "آزمون نهایی نزدیک است.", c = "خوش.\nما بر Nalorakk غلبه کردیم. آخرین آزمون را گذراندیم.\nقبیله‌ام نسل‌ها دربارهٔ این روز ترانه می‌خواند و قصه می‌گوید." }
WoWFQ[92084] = { t = "فریب Halazzi", d = "این‌ها چه کسانی‌اند؟ از کجا آمده‌اند؟\nراهی از Numazon به این‌جا پیدا کرده‌اند؟ چطور؟ مه آن‌قدر غلیظ است که آدم نمی‌فهمد می‌آید یا می‌رود.\nو Halazzi کجاست؟\nجواب می‌خواهم... همین حالا!", o = { "Loa Speaker Tobui" }, p = "دیدم دارد روشن می‌شود، و ذهنم هم.", c = "مثل Akil'zon، Halazzi هم تماشا می‌کرد. صبر می‌کرد.\nاو هرگز Witherbarkها را رها نکرد." }
