WoWFQ[92163] = { t = "loa مورلاک‌ها", d = "دربارهٔ هیاهوی Atal'Abasi چیزی شنیده‌ای؟ murlocهای آن‌جا از چیزی به‌پا شده‌اند.\nبه‌نظر می‌رسد murlocها loa خودشان را احضار کرده‌اند. و این loa هم murlocها را به جنگ می‌خواند.\nخودم دیدمش! همین امروز از بالای این پرتگاه. بزرگ‌ترین murlocی که تا حالا دیدی!\nتنها من هم نیستم که دیده‌ام! اما بزرگان می‌گویند مشکلات بزرگ‌تری داریم. به‌ع!\nبهتر است وقتی murlocها ما را زیر و رو کردند، به درگاه من نیایند!", c = "چه چیز تو را به Loa of Murlocs کشانده، مسافر؟\n<King Mrgl-Mrgl lowers his voice to a whisper.>\nکمکم کن!" }
WoWFQ[92164] = { t = "جنون مورلاک‌ها", d = "این murlocها نزد من، Loa of Murlocs، آمده‌اند تا از مهاجمی شرور پناه بخواهند.\nDeepfin از اعماق اقیانوس برخاسته است. به این سرزمین هجوم آورده و زمینش را آلوده کرده!\nتو را مأمور می‌کنم، قهرمان، از این پادشاهی دفاع کنی و Deepfin را به دریا پس بزنی!\n<King Mrgl-Mrgl lowers his voice to a whisper.>\nشرِ مهاجمان را کم کن، شاید بومی‌ها دیگر برای محافظت به من نیاز نداشته باشند و بتوانم بروم!", o = { "Deepfin murlocs کشته‌شده" }, p = "منتظر بازگشت پیروزمندانه‌ات هستم!", c = "تمامش کردی؟\n<King Mrgl-Mrgl clears his throat when he sees one of his \"followers\" eyeing him suspiciously.>\nمنظورم این است که کار تمام شد. Deepfin دیگر مزاحم ما نخواهد بود!" }
WoWFQ[92165] = { t = "ماهی غذاست، نه رفیق", d = "صدای mrglهایتان را شنیدم، قوم من. شکم‌هایتان از گرسنگی grgl می‌کند!\nمهاجمان راه غذایی را که برای بقا لازم دارید بر شما بسته‌اند.\nقهرمانم را می‌فرستم تا ماهی جمع کند تا شکم‌ها دوباره سیر شود!\n<King Mrgl-Mrgl lowers his voice to a whisper.>\nیا اگر ماهی داری، همان‌طوری به من بدهی هم بد نیست؟", o = { "Murloc-Skewered Lynxfish" }, p = "پادشاهی‌ام برای یک ضیافت آماده است! آماده‌ای؟", c = "شاهد قدرت قهرمانم باشید! سیر شوید، قوم من، و دیگر گرسنه نمانید!" }
WoWFQ[92166] = { t = "مقلدِ پیشوا", d = "هم‌قوم‌های من! یکی از شما برگزیدهٔ من شد تا... برگزیده‌ام باشد!\nاو برای بزرگی آفریده شده و دستیار من است... یعنی، کاهنه! بله، کاهنهٔ loa!\nکاهنه‌تان گم شده؛ شاید همان Deepfinهای خیانتکار دزدیده باشندش.\nبرای نشان دادن قدرت عظیمم، قهرمانم را می‌فرستم تا پیدا کند و پیش شما برگرداند.\n<King Mrgl-Mrgl lowers his voice to a whisper.>\nدستیارم گم شده و من هم گیر این‌جام! پیدایش کن و به او بگو بالای معبد منتظرم!", o = { "سرنخ اول پیدا شد", "سرنخ دوم پیدا شد", "\"Priestess\" پیدا شد", "Assistant Grgl-Grgl نجات یافت" }, p = "<Name>! فرمان می‌دهم کاهنه‌ام را سالم برگردانی.", c = "پیدایش کردی! ممنونم! یعنی... منظورم این است که... Loa of Murlocs به تو لطف می‌بخشد، قهرمان." }
WoWFQ[92167] = { t = "تنها یکی باید بماند", d = "دیده‌ام که Deepfinها murlocهای بومی را می‌ربایند و از جسد ترول‌ها undead می‌سازند. اما از این هم جلوتر نمی‌روند--همه را با خود به دریا می‌برند.\nبه‌نظر می‌رسد پیشوایشان murlocی قدرتمند است که در امنیت، دور از ساحل، پنهان مانده و پیشکش‌های پیروانش را می‌پذیرد.\nمی‌توانیم بیرونش بکشیم. اگر این لباس murloc را بپوشی و پیشکش تقدیم کنی، شاید فریب بخورد و خودش را نشان دهد.\nاگر رهبر را از بین ببریم، شاید بتوانیم murlocهای بومی را نجات دهیم!", o = { "پوشیدن Spare Murloc Suit", "پیشکش تقدیم شد", "Deepfin leader کشته‌شده", "Spare Murloc Suit" }, p = "باید Deepfin از این سرزمین‌ها ریشه‌کن شود!", c = "رهبر یک kobyss بود؟ اصلاً kobyss چی هست؟!\nیعنی... خوب کار کردی، قهرمان! به loaات خوب خدمت کردی!\nحالا که این murlocها در امنیت‌اند، وقت رفتن ماست!" }
WoWFQ[92447] = { t = "ماهیگیرانِ گرداب", o = { "Complete Event" } }
WoWFQ[92450] = { t = "بزرگ شدن سخت است", d = "آه، سلام! تو تازه‌ای. من Ani هستم. این هم Jynx.\nتا حالا آبشار را دیدی؟ بچه‌ها همدیگر را تشویق می‌کنند از رویش بپرند، ولی من خیلی می‌ترسم.\nمی‌خواهی ببینیش؟", o = { "نزد Ani در آبشار صحبت کن", "Cook Conversation", "Ani تا آبشار همراهی شد" }, c = "دیدی؟ حسابی بالاست." }
WoWFQ[92451] = { t = "فکر می‌کنم می‌توانم", d = "آره، حسابی پایین است.\nولی اگر نپرم، مسخره‌ام می‌کنند. شاید اگر تشویقم کنی، بتوانم؟", o = { "به Ani کمک کن بر ترسش غلبه کند." }, p = "دیگر نمی‌خواهم مسخره‌ام کنند. م-می‌توانم. فکر کنم می‌توانم...", c = "<Ani's bag of treasured trinkets sits empty on the marsh bank, already sinking into the soft mud.>" }
WoWFQ[92452] = { t = "بر طبق برنامه پیش نرفت", d = "<Ani's trinket bag sits in the soft mud of the river bank, but her trinkets are nowhere to be found.\nIf you're lucky, you may be able to follow her trail.>", o = { "وسایل Ani بازیابی شد", "Ani را از Bog نجات بده." }, c = "نمی‌دانستم چقدر دیگر دوام می‌آورم. سنگ‌هایم تمام می‌شد!" }
WoWFQ[92453] = { t = "بی‌باک", d = "آن مارمولک‌ها ته آبشار کمین کرده بودند و من را کشیدند!\nوسایلم را پیدا کردی؟ ولشان کردم که یکی پیدایشان کند. باورم نمی‌شود جواب داد!\nفکر کنم ترسانشان کردی. حالا باید امن باشد که Jynx کمکم کند بیرون بیایم.", o = { "با Ani در Amani'zar Village دیدار کن" }, p = "پریدن از آن آبشار دیگر آن‌قدرها هم ترسناک نیست.", c = "سلام، <name>! از آبشار پریدم و یک مارمولک بزرگ را کشتم!\nمی‌دانم تو کمک کردی.\nJynx هم کمک کرد.\nممنون!" }
WoWFQ[92492] = { t = "ارج به قربانی", d = "باز هم hash'ura. کمکم می‌کنی، یا Zul'jarra بند پایت را کوتاه گرفته؟\nنه؟ پس کاری برایت دارم. یکی از نگهبانانم، Idago، در کشتار Revantusk Sedge کشته شد. می‌خواهم با مراسم سوگواری ارجش را نگه دارم. ما Revantuskها جسد مردگانمان را می‌سوزانیم. اما جسد Idago را نداریم.\nپس می‌روم به sedge چیزی از او را بردارم. به جایش همان را می‌سوزانیم.\nنگهبان افتخاری‌ام Pel'na حاضر نیست بیاید و می‌گوید خطرناک است، ولی تو مرا در امنیت نگه می‌داری، این‌طور نیست؟", c = "سرت را پایین بگیر، <name>! جای کمینم را لو نده." }
WoWFQ[92493] = { t = "آنچه از Idago مانده", d = "Idago مطمئن‌ترین نگهبان من بود. از وقتی خودم را می‌دانم، راهنمای من بود. فکر نمی‌کردم آن‌قدر زود از دستش بدهم--و بعد Twilight's Blade بدون خبر حمله کرد.\nIdago همان کسی بود که مرا از دهکده بیرون کشید. نیزه و پرچمش را جا گذاشت. یادداشتی هم که به من داده بود جا مانده، در صورتی که او...\nآن وسایل را برایم بیاور. با آن‌ها می‌توانیم به زور بازویش و وفاداریش ارج بگذاریم--و روحش را روانه کنیم.", o = { "Idago's Warspear", "Idago's Banner", "Idago's Letter" }, p = "هرگز جلوی قومم نمی‌گویم، اما هر روز برای Idago عزادارم.\nنمی‌دانم بدون راهنمایی‌اش چطور ادامه دهم.\nRevantusk Sedge پر از این جادوگران پلید است. کار تو کار loaهاست.", c = "Idago را به سردابه بردند! می‌گویند آن رئیس بزرگ، Mish'mosh، برایش چیزی نفرت‌انگیز در نظر گرفته." }
WoWFQ[92495] = { t = "اختلال در کار Twilight's Blade", d = "نگاه کن این فرقه‌ای‌ها با Revantusk Sedge چه کردند!\nاین‌جا روزی جای آرامش بود... خانهٔ ما. و آن‌ها دارد بی‌حرمتی‌اش می‌کند.\nمی‌دانم برای برداشتن وسایل Idago آمده‌ایم، اما اگر به Twilight's Blade اسلحه بیندازی، اعتراضی نمی‌کنم.\nبه خاکشان بسپار--به آن‌ها خشم خرس را نشان بده.", o = { "Twilight Enforcer کشته‌شده", "Twilight Shadowmage کشته‌شده", "Baleful Darkspawn کشته‌شده", "Void Splinter" }, p = "یک روز به سمت این مهاجمان راه می‌افتیم و sedge را پس می‌گیریم!", c = "به کام Nalorakk سوگند، ضربه‌ای به نیروهایشان زدی." }
WoWFQ[92496] = { t = "نیزه در برابر سایه", d = "Idago هنوز زنده است، <name>!\nدیدم که با نشان‌های جادویی بسته شد و او را به سردابه بردند.\nفرقه‌ای‌ها می‌گویند می‌برندش پیش یک Deathchanter Mish'mosh. این فرقه‌ای باید پشت مرگ و ویرانی‌ای باشد که به sedge ما آوردند.\nبه افتخار آدم‌هایی که از دست دادیم، این مار را از خانه‌مان بیرون بکش!", o = { "Deathchanter Mish'mosh کشته‌شده" }, p = "دنیا بدون لکهٔ شرارت Mish'mosh جایی بهتر است.", c = "با دفاع از سرزمینمان در برابر Twilight's Blade، برای قبیله‌مان افتخار بزرگی آفریدی.\nاما Idago خوشش نمی‌آید که من برگشتم." }
WoWFQ[92497] = { t = "جادویی به تمام معنا", d = "تو... تو کی هستی؟ کی فرستادت؟ Lilaju؟\nفرقه‌ای‌ها دهکده را کشتار کردند. من عقب ماندم تا مطمئن شوم همه بیرون می‌روند.\nاما مرا گرفتند و حالا می‌گویند برای Idago چیزی خیلی خاص در نظر گرفته‌اند. دوست ندارم بفهمم چیست.\nاین جادویی که نگهم داشته کار ناآزموده‌ای است. افسون‌های باز کردن این بندها قطعاً در کتاب‌های جادویی‌ای است که فرقه‌ای‌ها آورده‌اند.\nکتاب‌ها را پیدا کن و چند صفحه ازشان بکَن. بعد می‌توانیم کلمات درست را کنار هم بگذاریم تا آزادم کنی.", o = { "Page of Binding", "Page of Pain", "Runic Bindings باز شد" }, p = "پیش از آزاد کردن Idago:\nفقط چند صفحه از کتاب‌ها بکَن و بیار این‌جا. بقیه‌اش ساده است.\nبعد از آزاد کردن Idago:\nلطف کردی، <name>. هم برای آزاد کردن من، هم برای چشم‌دوختن به این یکی.", c = "این‌که دختره چقدر بچه‌گری کرد به کنار، جانم مدیون تو است." }
WoWFQ[92499] = { t = "داناترین رهبران هم پیروی می‌کنند", d = "Idago یادم آورد که نخستین وظیفه‌ام قبیله‌ام است. دلم برایش تنگ شده بود، اما درست نبود که جان خودم--یا جان تو--را برای پیدا کردنش به خطر بیندازم.\nPel'na سعی کرد این را بگوید. گوش نکردم.\nباید الگوی قومم باشم. اجازه می‌دهم loa خرس راهم را نشانم دهد. گاهی باید از چیزهای عزیز بگذریم.\nای Nalorakk، به من استقامت و تاب‌آوری عطا کن.", c = "بر تصمیمم می‌ایستم، اما باید از Pel'na و Idago عذرخواهی کنم.\nآن‌ها حکمتی برایم دارند... و در عوض، من هم در این روزهای دشوار راهشان را نشان می‌دهم." }
WoWFQ[92531] = { t = "نیایشگاه loa پزشکی", d = "هر کسی راه خودش را برای فهمیدن دارد، حتی Akutu. البته متأسفانه هنوز پایش را در آن نگذاشته.\nنیایشگاه من روزی جای کشف و فهم برای Amaniها بود. لطفاً به آن‌ها پیام برسان که بازگشتشان را خوش‌آمد می‌گویم.\nارواح به مرور آرام می‌شوند.", p = "چرا کمکم نمی‌کنی؟!", c = "چه قصهٔ روحی!\nدلم می‌خواهد باز هم با Sij'ta حرف بزنم، و این که Kulzi گویندهٔ loaاش را از دست داده مرا اندوهگین می‌کند، اما خوشحالم که Sij'ta سرانجام به آرامش رسید.\nمی‌روم با Kulzi صحبت کنم. امیدوارم دلخوری در کار نباشد." }
WoWFQ[92557] = { t = "ارج به شعله", d = "Fetna Alai-nazdo دوباره از راه رسیده است!\nاگرچه گذرش تاریک است، شعله‌اش در وجود همهٔ ما می‌درخشد!\nباد این چرخشِ فصل درخشان باشد و شانس خوبی برای تو و همهٔ آن‌هایی که Fetna Alai-nazdo را جشن می‌گیرند بیاورد!", c = "شعلهٔ Zul'Aman را به ارجِ Jan'alai برافروز." }
WoWFQ[92907] = { t = "پاسخ‌های Amani", d = "عمو آمادهٔ هم‌آوایی با loaها شده تا دربارهٔ این Ula'tek اطلاعات پیدا کند. در این میان، ما می‌رویم سراغ جعبه‌هایش تا ببینیم چه می‌توانیم پیدا کنیم.\n<Zul'jan points to all the boxes scattered around the terrace.>\nعمو بزرگ‌ترین مجموعهٔ تاریخ‌ها را میان Amaniها دارد. من بچه که بودم همین‌ها را می‌خواندم.\nدنبال هر چیزی دربارهٔ Ula'tek، مارها یا تاریخ اولیهٔ Amani بگرد. این‌ها را من می‌گیرم، تو بقیه را بگرد.", o = { "جعبهٔ اول گشته شد", "جعبهٔ دوم گشته شد", "جعبهٔ سوم گشته شد", "Befuddled Amani Mask صید شد", "Befuddled Amani Mask را به Kinduru بده", "Woodworking Tool جمع‌آوری شد", "Woodworking Supplies جمع‌آوری شد", "Befuddled Amani Mask تعمیر شد", "تعمیر آغاز شد" }, p = "این نقاب چه می‌داند؟", c = "شنیدی چه گفت؟ یک سلاح!" }
WoWFQ[92916] = { t = "فریاد برای یاری", d = "<Name>، به‌عنوان یک هم‌راه hash'ura، باز هم از تو می‌خواهم که به Amaniها یاری رسانی. تهدید مهیب دیگری بر سرشان است.\nMalacrass بازگشته است.\nWitherbark Bluffs زیر تاخت‌وتاز دشمنی هیولاست که من هرگز مانندش را ندیده‌ام. و با برخوردی که با Twilight's Blade داشتیم، زمانش نمی‌تواند بدتر باشد.\nZul'jan ما را رها کرد و... فکر می‌کنیم دست‌کم تا حدی او مقصر است.\nسر هر دویشان خواهیم رفت. فعلاً کمکمان کن تا از بین نرویم.", c = "خدا را شکر که رسیدی.\nکار داریم." }
WoWFQ[92917] = { t = "رهایی اسیران", d = "<Liadrin wipes sweat from her brow and addresses you without turning. You see minor cuts and scrapes she has neglected to heal.>\nاز دروازه‌های شهر عقب نشستیم. زخمی و مسموم خیلی زیاد بود؛ Orweyna، Tak'lejo و من بهترین خدمت را به Amaniها همین‌جا می‌رسانیم.\nاما تو باید بیرون باشی و کمک Zul'jarra.\nمارهای Malacrass با Witherbarkها را می‌گیرند، دورشان می‌پیچند و پر از زهرشان می‌کنند.\nآزادشان کن--و حتماً Dak'zor را پیدا کن. او خط مقدم بود و اول از همه افتاد.", o = { "روستاییان نجات یافتند", "Dak'zor نجات یافت" }, p = "تکان بگیر، <name>! پیش از آن‌که Amaniهای بیشتری را از دست بدهیم!", c = "Dak'zor را بردند؟ به سمت شرق؟\n<Zul'jarra growls.>\nبه سمت تنگه. به سمت جزیره. آن‌جا چه می‌خواهند با او بکنند؟\nروح باشد یا نباشد، راهی پیدا می‌کنم تا گلوگاه آن Hex Lord را بگیرم..." }
WoWFQ[92919] = { t = "چه غرش، چه گاز", d = "زخم‌هایی که دیده‌ام... آن سرسختی.\nاین مارها نه فقط روی زمین می‌خزند و دور تن جنگجویانمان می‌پیچند، بلکه با تیغه‌های زهرآلودشان زخم عمیق می‌زنند و وقتی از آسمان شیرجه می‌زنند با چنگال‌هایشان نشانه می‌روند.\nZul'jarra و نیروهایش به‌تنهایی از پس این برنمی‌آیند، اما دست من این‌جا لازم است.\nبا پایین آوردنشان به Zul'jarra کمک کن.", o = { "مهاجمان کشته‌شده" }, p = "هیچ‌وقت مارها را دوست نداشتم... و این به‌هم‌ریختگی هم کمکی نمی‌کند.", c = "به لطف تو جنگ به سود ما چرخیده، اما کار تمام نیست.\nحالا کمی نفس می‌کشیم، اما باید به سرچشمه ضربه بزنیم--Malacrass--قبل از آن‌که مارهای بیشتری رویمان خزیده شوند." }
WoWFQ[92920] = { t = "فرود آسمان‌ها", d = "کمی زمان می‌برد تا Akil'zon را بخوانم و راه را باز کنم. و این‌جاست که تو به کار می‌آیی.\nمحافظتم کن، hash'urای من.\nجانم را به تو می‌سپارم. قبلاً هم جهش‌های بزرگی زده‌ایم، نه؟", o = { "با Zul'jarra صحبت کن", "از Zul'jarra محافظت کن" }, c = "loaها نمی‌توانند با ما بیایند؟ پس باید به قدرت خودمان تکیه کنیم." }
WoWFQ[92921] = { t = "به سوی Skybridge", d = "<Zul'jarra's face is dark with rage as she looks off towards the Skybridge.>\nZul'jan... گذاشتی آن مار Malacrass ذهن و قلبت را آلوده کند. برای چه؟ قدرت؟\nموضوع lightwood یک چیز بود. اما این؟\nنمی‌دانم Malacrass برای اسیران چه در سر دارد، اما باید جنگ را به سمت خودش ببریم و دور از قوممان نگه داریم.\nرد هیولاها را برگرد Skybridge دنبال کن. من با loaها هم‌آوا می‌شوم و آن‌جا به تو می‌پیوندم.\nبا یاری‌شان، جلوی این کار را می‌گیریم.", c = "خودم راه Malacrass را می‌گیرم، حتی اگر ناچار شوم فلس هزار تا از این هیولاها را بکنم." }
WoWFQ[92951] = { t = "کاوش ژرف‌تر", d = "نقاب می‌گوید دنبال طومارهای Malacrass می‌گردیم. تا در Maisara هستیم، هر طوماری که Vilebranchها جا گذاشته‌اند پیدا کن.\nMaisara جای خطرناکی است، پس وقت نگذار برای دست‌وپا کردنشان--همین‌طوری بردار و بعداً با هم چک می‌کنیم.\nحتی اگر چیزی دربارهٔ Ula'tek نگفته باشند، شاید چیزی از نقشه‌ها یا نیت‌شان علیه Amani‌ها در آن‌ها باشد.", o = { "Vilebranch Scroll", "بیرون Maisara Deeps با Loa Speaker Kinduru دیدار کن." }, p = "این جست‌وجوی Ula'tek دارد از چیزی که Zul'jan تصور می‌کند خطرناک‌تر می‌شود.", c = "<Kinduru takes the bundle of scrolls. He says nothing, but is clearly concerned.>" }
WoWFQ[92952] = { t = "مأموریت در Maisara", d = "جادو کمک کرد، اما... کافی نبود. هنوز اسمم و زندگی قبلی‌ام را یادم نمی‌آید. شاید آن دانش برای همیشه گم شده باشد...\nاما چیزهای بیشتری دربارهٔ Ula'tek یادم می‌آید--یا دقیق‌تر، این‌که کجا می‌توانیم اطلاعات بیشتری پیدا کنیم!\nVilebranchها مرا مجبور کردند در این شکل بمانند. آن‌ها دانش تاریک را از قبیله‌های دیگر پنهان می‌کردند، از جمله دانش دربارهٔ Ula'tek.\nاگر می‌خواهیم بیشتر بدانیم، باید به Maisara Deeps برویم.", o = { "کمی بمان و به Zul'jan گوش کن", "به Maisara Deeps برس" }, c = "Malacrass مرده، اما معنایش این نیست که دانشش از بین رفته." }
WoWFQ[92953] = { t = "خاطرات Malacrass", d = "وقتی خدمتکار Vilebranchها بودم، صحبت‌هایی دربارهٔ پژوهش‌های Malacrass روی Ula'tek به گوشم خورده بود.\nMalacrass دانسته‌هایش را در طومارهایی ثبت می‌کرد که همیشه همراهش بود. حالا که مرده، باید بفهمیم سرشان چه شد.\nاستادان hex نزدن به‌راحتی حرف نمی‌زنند... اما اگر بکشیشان، می‌توانم جادوی نکرومانسی خودشان را علیه‌شان به کار ببرم تا مجبورشان کنم حرف بزنند.", o = { "Hex Master Jintagga بازجویی شد", "Hex Master Soye'mal بازجویی شد", "Hex Master Uy'okan بازجویی شد", "بیرون Maisara Deeps با Loa Speaker Kinduru دیدار کن." }, p = "چه فهمیدی؟", c = "Maisara Caverns حتی از Deeps هم خطرناک‌تر است، و Vordaza به‌اندازه‌ای که بی‌رحم است، کشنده است." }
WoWFQ[92954] = { t = "غارهای Maisara: ارباب ارواح", d = "یادداشت‌های Malacrass دست Vordaza است و برای پیش بردن آزمایش‌های نکرومانسی‌اش از آن‌ها استفاده می‌کند.\nلازم است به داخل Maisara Caverns بروی و آن‌ها را پس بگیری. خطرناک است و قبل از ورود باید متحد جمع کنی.\nمن این‌جا می‌مانم و از عمویم محافظت می‌کنم. باید همهٔ طومارهایی را که جمع کرده‌ایم بگردیم تا ببینیم چه چیز دیگری دستگیرمان می‌شود.", o = { "کمی بمان و به Kinduru گوش کن", "با Zul'jan صحبت کن تا ورود به follower dungeon آغاز شود", "Malacrass's Notes" }, p = "آیا یادداشت‌های Malacrass سرنخ بعدی را دارند؟ یا این‌که همه‌اش هدر دادن وقتمان است؟", c = "پیدایشان کردی. حالا ببینیم این‌همه زحمت می‌ارزید یا نه.\n<Zul'jan flips through the scrolls.>" }
WoWFQ[92955] = { t = "لوح‌های Numazon", d = "نیاکان در برابر loa سر فرود نیاوردند--یک سلاح طلب کردند! سلاحی که به پیروزی‌مان انجامید.\nباید بیشتر بدانم.\nگفتی لوح‌های Numazon قدیمی‌ترین لوح‌های Zul'Aman هستند. می‌توانیم جست‌وجو را آن‌جا ادامه دهیم. شاید Amani‌های باستانی سرنخی برایمان باقی گذاشته باشند.\nعمو می‌گوید نقاب را هم ببریم. شاید یک خاطرهٔ پراکنده کلید حل این راز باشد.", o = { "در Numazon با Zul'jan دیدار کن." }, c = "عمو نمی‌فهمد. Ula'tek می‌تواند همه‌چیز را عوض کند." }
WoWFQ[92957] = { t = "راز سنگ‌نوشته‌ها", d = "اگر لوح‌ها زمانی ساخته شده‌اند که Amani‌ها تازه به Zul'Aman رسیده بودند، پس باید سرنخی از Ula'tek همین‌جا باشد.\nلوح‌ها برای حمل آن‌قدر سنگین‌اند، برای همین عمو پیشنهاد داد از نوشته‌ها روی‌نگار بگیریم.\nجلوتر رفتم و چند تا گرفتم، اما به Vilebranchها خوردم. برگشتم این‌جا تا مطمئن شوم عمو امن است.\nبه داخل Numazon برو و روی‌نگارهای بیشتری بردار، من حواسم به عمو هست. مواظب Vilebranchها باش.", o = { "Amani Tablet Rubbing" }, p = "بگذار نگاهی به روی‌نگارها بیندازم...", c = "این‌جا را نگاه کن! می‌گوید Amani‌ها یک مار بزرگ را احضار کردند تا از دشمنی وحشتناک نجاتشان دهد.\nو این‌جا، مار پیروز شد اما Amani‌ها آن را مهر و موم کردند.\nنخستین نیایشگاهی که در Atal'Aman ساخته شد به مار وقف داده شده بود.\n<Kinduru continues to analyze the rubbings.>" }
WoWFQ[92958] = { t = "تخلیهٔ مغز", d = "کاش می‌توانستم بیشتر کمک کنم اما... این حفره‌های حافظه‌ام. به‌خاطر آسیبی که نقاب دیده، مدتی طولانی جادو از آن نشت کرده.\nتو بخش فیزیکی نقاب را تعمیر کردی، اما جادوی درونش هنوز ضعیف است.\nZul'jan می‌گوید ترول‌های Vilebranch این سردابه را اشغال کرده‌اند. جادویی که من را سرپا نگه می‌دارد شبیه جادوی خودشان است.\nشاید بتوانی کمک کنی. نشان‌های hex آن‌ها را بیاور--باید بتوانم جادویشان را از آن‌ها بگیرم.", o = { "Vilebranch Hex Fetish" }, p = "جادوی Vilebranchها آن‌قدر آشنا به نظر می‌رسد... نکردند مرا در این نقاب زندانی کنند؟", c = "فقط یک لحظه می‌برد تا جادو را از نشان‌ها بگیرم." }
WoWFQ[93010] = { t = "نیایشگاه مار", d = "این‌جا! یادداشت می‌گوید Ula'tek توسط Amani‌ها مهر و موم شد. برای شکستن مهر، «کلیدی» لازم است.\n<Zul'jan flips through the notes.>\nکلید درون نیایشگاهی پنهان شده بود و با جادویی باستانی محافظت می‌شد. اما کدام نیایشگاه...\n<Zul'jan looks up.>\nلوح‌های Numazon از نیایشگاهی نگفتند که «به پیروزی مار وقف» داده شده بود؟ از رؤیاهای Harandar می‌دانیم که Ula'tek یک مار بود.\nباید همان باشد! کلید در نیایشگاه مار، در Atal'Aman، پنهان است!", c = "این نیایشگاه باستانی است. کوچک. عادی.\nجای پنهان‌کاری بی‌نقصی است." }
WoWFQ[93011] = { t = "میراث Amani", d = "اگر Malacrass درست می‌گفت، کلید Ula'tek باید همین‌جا باشد.\n<Zul'jan's heavy hammer thumps onto the shrine for emphasis.>\nشاید کمی طول بکشد تا سنگ را بشکنم و پیدایش کنم.\nنمی‌دانم نیاکان چه محافظتی در کار گذاشته‌اند، اما تو باید سرت را با آن‌ها گرم کنی تا من کارم را بکنم.\nاعتراف می‌کنم رؤیاهای Harandar را باور نمی‌کردم. یادداشت‌های Malacrass را هم کاملاً قابل اعتماد نمی‌دانم.\nاما اگر کلید این‌جا باشد، اثباتی انکارناپذیر است که چیزی که دنبالش هستیم واقعی است.", o = { "از Zul'jan در حین پیاده کردن نیایشگاه مار محافظت کن.", "با Zul'jan صحبت کن", "با Kinduru صحبت کن" }, c = "The Amani found you and Kinduru at Atal'Aman. They carried you back here." }
WoWFQ[93012] = { t = "بن‌بست", d = "بعد از نشست Harandar به این‌جا آمدم تا با Zul'jarra دربارهٔ رؤیایی که دیدی حرف بزنم. Zul'jan وقتی رفتی آشفته به نظر می‌رسید و قصدم آشفته کردنش نبود.\nاما همهٔ این‌ها می‌تواند صبر کند. حالا که به هوش آمدی، بهتر است بروی سراغ Zul'jarra. او می‌خواهد بداند در Atal'Aman چه گذشت.", o = { "با Zul'jarra صحبت کن", "با هاون Kinduru گیاهان Bog را بسای", "مخلوط آیین مردگی را در آتش‌ها بریز" }, p = "چطور چنین چیزی ممکن شد؟", c = "دیده‌بان‌هایی را برای پیدا کردن Zul'jan فرستاده‌ام، اما پوشاندن این‌همه زمین ناممکن است. دعا می‌کنم پیش از آن‌که دیر شود دروغ‌هایی که Malacrass بافته است را ببیند.\n<Zul'jarra's expression is grim, then softens as a small eagle lands on your shoulder.>\nممنونم، <name>، که ماجرا را برایم گفتی و در لحظه‌های آخر کنار عمویم بودی.\nاین عقاب همراه همیشگی عمویم در گردش‌هایش در Zul'Aman بود. فکر می‌کنم راضی می‌شود اگر حالا که او نیست، تو از او مراقبت کنی." }
WoWFQ[93047] = { t = "اصول قصابی", d = "با این‌که این سربازها چقدر می‌خورند نمی‌توانیم کنار بیاییم. کمی از وقتت را به ما بده تا این ارتش را سیر کنیم، خب؟\nبه گراز نیاز داریم. نه فقط یکی دو استیک؛ کل گراز را می‌خواهیم. هیچ چیز هدر نمی‌رود، باشد؟", o = { "Boar Carcass", "Boar Carcass گذاشته شد" }, p = "هنر شکار Amani پایبندی است. تمرین می‌کنی تا مهارت‌ها مثل نفس کشیدن طبیعی شوند.\nاما همین حالا، پایبندی یعنی کاری که من می‌گویم انجام بدهی.", c = "تو حسابی شکارچی هستی، ثابت شد. ممنون که این‌جا کمکمان کردی." }
WoWFQ[93048] = { t = "ریتم ندارد", d = "آن پسر، Kovu، بی‌این‌که حتی یک قدم امتحان کند از این‌جا زد بیرون. فکر می‌کند دو پای چپ دارد، اما حاضر نیست حتی امتحان کند.\nتو به‌نظر یک مبارز توانمند می‌آیی. چنین چیزی برایش احترام می‌آورد.\nشاید فقط به یک شریک رقص درست نیاز دارد تا قدم‌ها را نشانش بدهد. کمکش کن، خب؟", o = { "با Kovu صحبت کن" }, p = "پیشرفتی، نه؟", c = "آن پسر هنوز تمرین زیادی لازم دارد، اما کمک کردی از سرش بیرون بیاید و فقط ریتم را حس کند." }
WoWFQ[93049] = { t = "کمک در تکالیف", d = "<The little girl keeps her voice low, making sure her father doesn't overhear.>\nدوست‌هایم می‌روند پایین، جایی که shade lilyها می‌رویند، اما من باید یک عالمه کار خسته‌کنندهٔ apothecary انجام بدهم.\nبابا می‌خواهد چند گیاه جمع کنم برای مرهم‌ها و پمادهایی که برای شفا به کار می‌روند. گفتم شاید بعداً شود، گفت نه.\nچه می‌شود... تو به من کمک کنی؟ فقط این یک بار، لطفاً؟", o = { "Pristine Shade Lily", "Dragonhawk Fern Frond" }, p = "همه‌شان را آوردی؟", c = "همه در حالت بی‌نقص!\nشاید بهتر باشد شاگرد به‌جای من تو باشی." }
WoWFQ[93050] = { t = "تاریخچهٔ محراب‌ها", d = "محراب‌ها هر از گاهی باید از قدرت loaها پر شوند.\nمن دیگر به‌چابکی قدیم نیستم و محراب‌ها همه پراکنده‌اند.\nبه یک شمن پیر کمک کن، خب؟ totem خودم را به تو می‌دهم تا قدرت loaها را به محراب‌ها برسانی.\nو شاید در این حین بتوانی یک دو چیز هم از من و شاگردهای دیگر یاد بگیری.", o = { "Nalorakk Altar شارژ شد", "Jan'alai Altar شارژ شد", "Halazzi Altar شارژ شد", "Akil'zon Altar شارژ شد", "Rakan's Totem" }, p = "فقط باید کمی همین‌جا نفس تازه کنم.\nبرای من نگران نباش. حواست به کار همین‌جا باشد، خب؟", c = "روزهای نبرد من پشت سر است، اما خوشحالم که می‌توانم دور دهکده کمک کنم." }
WoWFQ[93051] = { t = "آزمون نهایی", d = "تمرین من تقریباً تمام است!\nفرمانده‌ام می‌گوید پیش از آن‌که برای میدان جنگ پیشنهادم کند، باید خودم را در برابر یک مبارز قوی ثابت کنم.\nاما بعد از... راستش، بعد از آن‌چه دفعهٔ قبل شد، این‌قدرها کسی را پیدا نکرده‌ام که حاضر باشد با من تمرین کند...\nتو به‌نظر توانمند می‌آیی. و هول‌انگیز. حوصله داری کمکم کنی؟\nو با من تعارف نکن، باشد؟ من می‌توانم تحملش کنم.", o = { "به Ri'kari بگو آمادهٔ شروع هستی", "سرباز تازه‌کار Dar'rak تمرین شد" }, p = "حتی یک ضربه را هم کوتاه نکن. پسر باید با توان خودش موفق شود یا شکست بخورد.\nاگر آماده نیست، با فرستادنش به میدان بی‌آموزه، هیچ لطفی در حقش نکرده‌ای.", c = "خوب جنگیدی.\nقدرت خودت ثابت کرد که Dar'rak می‌تواند در برابر جنگجویانی خیلی قوی‌تر از خودش سرپا بماند.\nهیچ‌وقت فکر نمی‌کردم تو را ببرد، <name>. اما این‌که هنوز نفس می‌کشد به‌خودی‌خود دستاورد بزرگی است، نه؟" }
WoWFQ[93093] = { t = "غنایم gnarldin", d = "من را فرستاده‌اند تا ثابت کنم آمادهٔ warrior شدن در میان Amani‌ها هستم. هر کس این افتخار را می‌خواهد باید خودش را ثابت کند.\ngnarldinها را انتخاب کردم چون نزدیک‌اند، و شنیدم Zul'jarra کمی نرمشان کرده.\nبه‌نظر می‌رسد من تنها کسی نبودم که این فکر را کرد و اشتباه کرد.\nاما هنوز به جمع کردن هر چه بیشتر غنیمت از gnarldinها نیاز دارم.\nاگر hash'uraی بزرگ مثل تو کمکم کند، هیچ راهی برای باختن من نیست، نه؟\nغنایم را تو جمع کن. من عقب می‌مانم تا پشت‌هایمان را ببینم.", o = { "Gnarldin Trophies" }, p = "غنایم را آوردی؟ gnarldinها از همهٔ آن جنگ‌هایشان از این‌ها زیاد دارند.", c = "این... این خیلی غنیمت است، hash'ura." }
WoWFQ[93094] = { t = "پیروزی غارتی", d = "بسیاری از جنگجویان از وقتی gnarldinها به Zul'Aman آمدند با آن‌ها روبه‌رو شدند، اما خیلی‌هایشان شکست خوردند.\nفکر می‌کردند حالا که gnarldinها در سرزمین ما و تضعیف شده‌اند، کارشان راحت‌تر بوده...\nشکارچی‌های gnarldin لوح‌های شکارچی‌های Amani را که این‌جا افتادند جمع کرده‌اند.\nاما با تو کنارم، می‌توانیم برای کسانی که این‌جا جان باختند «انتقام» بگیریم--بدون کشتن و خطر افتادن جان.\nلازم نیست gnarldinها را بکشیم. فقط باید به‌قدر کافی نزدیک شویم تا لوح‌ها را برداریم. چه می‌گویی؟", o = { "Hunter's Tablet" }, p = "با این لوح‌ها، هیچ‌کس نمی‌تواند قدرت ما را زیر سؤال ببرد!", c = "کافی است!\nهمه‌شان واقعاً مرده بودند... نه؟" }
WoWFQ[93095] = { t = "خشم تلخ", d = "رهبر gnarldinهای این‌جا به Tusk Taker معروف است. یک حدس بزن چرا این اسم را دارد.\nیک غنیمت در غاری دارد که این یکی نگهش می‌دارد. بردارش، و او برای جنگیدن بیرون می‌آید.\nبرای من شکستش بده، و دیگر هیچ‌کس حق warrior شدن من را زیر سؤال نمی‌برد.", o = { "Tusk Taker's Taken Tusk Trophy برداشته شد", "Tusk Taker کشته‌شده" }, p = "Tusk Taker را هنوز نکشتی؟", c = "آها! Tusk Taker مرد!\nحالا بقیه مرا یک warrior واقعی Amani می‌بینند--وقتی به آن‌ها بگویم تمام غنایمی که Tusk Taker را کشت را خودم برداشتم." }
WoWFQ[93096] = { t = "شرف Amani", d = "همهٔ غنایمی که لازم بود همین‌ها هستند.\nمی‌برمش‌ان به نقطهٔ دیدار نزدیک. فقط باید آن‌جا منتظر Huntmaster Jinki بمانیم تا برسد. بیا!\nبیا!", o = { "به نقطهٔ دیدار Amani برس", "پاداش Amani دریافت شد" }, c = "این سرنوشتی شرم‌آور برای Kel'vujo است، اما سرنوشتی است که خودش برگزید.\nتو، hash'ura، باز هم ثابت کردی که قوی هستی.\nاین را به‌عنوان پاداش کمک به جدا کردن ضعیف‌ها و بی‌لیاقت‌ها از جنگجویانمان بگیر." }
WoWFQ[93178] = { t = "قدم‌زنیِ نیمه‌کاره", d = "خودِ hash'ura! محبوبِ loa زبردست ما! شاید بتوانی کمک کنی...\nپدرم، Oban، مریض است و این روزها همهٔ حواسم به اوست.\nیک ساعت پیش وقتی پشت کردم، دخترم، Kanza، زد بیرون!\nکل دهکده را گشتم، اما بیشتر از این نمی‌توانم جایی بروم و پدرم را تنها بگذارم.\nلطفاً می‌روی ببینی کجاست؟ خودش می‌تواند از خودش مراقبت کند، اما دختر حساسی است و نمی‌خواهم دور شود.\nآن پسر احمق Haz'kel پایین نمی‌آمد، اما شاید دیده باشد کجا رفت. اول از او بپرس.", o = { "با Haz'kel صحبت کن", "پل چوبی پیدا شد", "سرنخ اول پیدا شد", "سرنخ دوم پیدا شد", "سرنخ سوم پیدا شد" }, p = "خیلی نگران Kanza هستم!\nنباید تنها باشد.", c = "پشت پل چوبی چه کاری داشت؟ گفته بودم آن‌جا نرود.\nبا سبد من و بهترین قوری چای‌مان؟\nآه... آه، نه. می‌شود؟! و تنها؟" }
WoWFQ[93179] = { t = "سرسپردگیِ کودکانه", d = "رفته سمت نیایشگاه Filo. برای آن‌جا خیلی بزرگ شده. تقریباً سیزده‌ساله است--یک بزرگ‌سال.\nFilo loa کودکی است و از بچه‌ها محافظت می‌کند. والدین برای بچه‌های سالم از Filo طلب برکت می‌کنند.\nحتی می‌گویند اگر بچه‌ای بمیرد، Filo در دنیای دیگر کنارش می‌ماند تا والدینش سراغش بیایند.\nاین خرافه است، اما به‌خاطر همین دارد می‌رود.\nما دوقلویش، Janaka، را از دست دادیم. باید فکر کند او پیش Filo است.\nراه نیایشگاه Filo خطرناک است و آن loa هم حرفی با او نمی‌زند. هر کاری می‌توانی بکن تا بیاید خانه!", o = { "با Nerunda صحبت کن", "Kanza پیدا شد" }, p = "<Kanza eyes you uncertainly.>", c = "<You do not want to take the child back by force, but perhaps you can persuade her to listen to you by helping her with what she is trying to accomplish here.\nJudging by the items arrayed before Filo's shrine, she is preparing some sort of ritual.\nPerhaps if you help her with the ritual, she may go with you--or go home on her own.>" }
WoWFQ[93180] = { t = "آماده‌سازی نیایشگاه", d = "<Kanza makes no sound but briefly meets your gaze. She points off toward the hot spring pools.\nMaybe she wants you to do something there?>", o = { "Kanza همراهی شد", "Kanza دوباره همراهی شد", "Stinger Hatchling کشته‌شده", "Stinger Matriarch کشته‌شده", "Thorncap", "Thorncapها جمع شد" }, p = "<Kanza shifts her weight from foot to foot, swaying impatiently.>", c = "<Kanza claps and jumps up and down excitedly.\nBut she pulls at your sleeve and makes an arcing motion with her hand, pointing into the far distance.\nThere is something else she wants you to do.>" }
WoWFQ[93181] = { t = "معبد و یک قوری", d = "<Kanza is dancing with excitement.\nShe holds her small hand with one finger up.\nOne last thing to do.\nYou must almost be ready for the ritual to summon Filo--if that is indeed what she is asking for your help to do.\nShe fishes in her tunic for something and presents an object to you: the broken handle of a teapot, presumably from the one she dropped on the way here.\nPerhaps she needs a substitute?>", o = { "Teapot از Honnu خریداری شد", "با Kanza صحبت کن", "Teapot گذاشته شد" }, p = "<Kanza looks nervous and expectant.>", c = "باید می‌دیدمش.\nفقط یک بار دیگر." }
WoWFQ[93182] = { t = "بازگشت به خانه", d = "می‌روم خانه.", c = "برگشتی! پیدایش کردی؟\nهمین الان دارد می‌آید، نه؟" }
WoWFQ[93257] = { t = "Revantusk در خطر", o = { "در Nalorakk's Prowl Kahanea را پیدا کن." } }
