WoWFQ[93259] = { t = "کوبیدن خرچنگ‌ها", o = { "10 تکه Mouthwatering Crab Meat از خرچنگ‌های بالادست ساحل برداشت کن." } }
WoWFQ[93260] = { t = "تله‌های خرچنگ", o = { "6 تلهٔ Crab Trap در بالادست ساحل را تمیز کن." } }
WoWFQ[93261] = { t = "خرچنگی به آن بزرگی", d = "رد آلودگی Void را بالادست رودخانه دنبال کردم و پیش از این‌که به غارش برود، یک هیولا دیدم: یک خرچنگ عظیم که Void به مغزش رخنه کرده. همان بود که آن تکه‌های آلوده‌کنندهٔ رودخانه را می‌ریخت!\nتا وقتی این جانور زنده است، همین‌طور آلودگی را پخش می‌کند و خرچنگ‌ها را با Void آلوده می‌کند. باید جلویش گرفته شود!\nدوست داشتم بمانم و بجنگم، اما باید به همه در Overlook خبر بدهم.\nلطفاً، <name>. آن خرچنگ را بکش و منبع آلودگی‌اش را از بین ببر، قبل از این‌که آدم‌های بیشتری از قومم را آزار بدهد!", o = { "Mania-Crab کشته‌شده", "Chipped Twilight's Blade Artifact" }, p = "نمی‌دانم Twilight's Blade این جانور را ساخته یا نه، اما باید برود!", c = "یعنی Twilight's Blade فقط به Revantuskها ضربه نزده، به حیات وحش ما هم زده؟ باید حواسمان به این فرقه‌ای‌ها باشد و Nalorakk's Prowl را از آلودگی‌شان محافظت کنیم!\nسلامتی قومم و خرچنگ‌هایمان اولویت اول من است. دیدن قحطی قومم زیر نظر من پر از خشم و گناه شد... انگار داشت یاد مادرم، رئیس river-walkerها، را لکه‌دار می‌کردم.\nکمک تو کمکم کرد به رهبری تبدیل شوم که river-walkerهایم به آن نیاز دارند.\nممنونم، <name>. برای همیشه پیش Revantuskها خوش‌آمدی." }
WoWFQ[93263] = { t = "باید همین می‌شد...", d = "Malacrass به این موجودها می‌گفت Children of Ula'tek.\nپس همین است. رؤیای من Zul'jan را به Ula'tek رساند و از Ula'tek به Malacrass. با هم، باید در پی او باشند.\nهر کاری از دستم بربیاید می‌کنم تا کمک کنم و این ماجرا را برای Zul'jarra و قومش جبران کنم.\nبیا تا جایی که می‌توانیم از این هیولاها بکشیم.\nرودررو می‌جنگیم و این دشمن مشترک را ریشه‌کن می‌کنیم.", o = { "مارها کشته‌شده" }, p = "فقط چند تا دیگر، بعد به سمت Atal'Utek--و سر و کله زدن با Malacrass و برادرم.", c = "مارها پراکنده شدند و ما هنوز سرپاییم.\nیک پیروزی کوچک. اما پیروزی‌ای است که می‌پذیرم." }
WoWFQ[93265] = { t = "بریدن سر مار", d = "<Zul'jarra is covered in sweat, blood, and venom. Her face is grim in a way you haven't seen before.>\nکمکم لازم دارم.\nچند سرباز را برای دیده‌بانی به کلبه‌ای در شمال فرستادم، برای محافظت از چند غیرنظامی Witherbark که آن‌جا گیر افتاده‌اند.\nاما یکی از برتان هیولا بویشان را گرفت. بکشش و غیرنظامی‌ها را نجات بده، پیش از آن‌که سرنوشتشان مثل Dak'zor شود!\nمن همین‌جا می‌مانم تا مطمئن شوم هیچ‌کدام از این مارها وارد lodge نشوند.", o = { "Nutek the Abductor کشته‌شده", "با Zul'jarra صحبت کن" }, c = "آن نقاب را له می‌کنم." }
WoWFQ[93266] = { t = "طبل برای سربازان", d = "loaها نبردمان را برکت داده‌اند!\nNalorakk و Halazzi در حال پاره کردن جناحینشان هستند. Akil'zon و Jan'alai از آسمان سرشان می‌کوبند.\nما در زمین می‌مانیم و از وسط به داخل می‌رویم--همه‌مان--و این آفت را از Zul'Aman می‌رویش.\nدوباره طبل بزن، hash'ura. جنگجویانمان را به نبرد در Atal'Aman بخوان. حالا متحد شده‌ایم و حرفمان را می‌شنوند!", o = { "طبل‌ها به صدا درآمد" }, p = "طبل بزن. نیروها را جمع کن. وقت زیادی نداریم.", c = "جنگجویانمان رسیده‌اند.\nو با کمک loaها، این \"Children of Ula'tek\" را نابود می‌کنیم.\nحالا نوبت خودِ Malacrass است!" }
WoWFQ[93409] = { t = "ندای کاوشگر: Atal'Aman", d = "<The fallen scout's body bears terrible wounds, but still clutches tightly to a report detailing an immanentsic Vilebranch attack on Atal'Aman.>", o = { "دلوی Atal'Aman در هر درجهٔ سختی کامل شد" }, p = "دعوا کرده‌ای، <name>؟", c = "خوب است. بهتر است یاد بگیرند در سوراخ‌هایشان بمانند." }
WoWFQ[93410] = { t = "ندای کاوشگر: سردابه‌های Twilight", d = "سردابه‌های باستانی Amani نزدیک Broken Throne از هیولا پر شده‌اند.\nپیش از آن‌که مردگان درونش بیشتر بی‌حرمتی شوند، متجاوزان را پاک کن.", o = { "دلوی Twilight Crypts در هر درجهٔ سختی کامل شد" }, p = "جنگ چطور پیش می‌رود؟", c = "یک روز Zul'Aman از لکهٔ این‌ها پاک می‌شود." }
WoWFQ[93432] = { t = "از شمشیر تا گاوآهن", d = "اول Mor'duun و Blade به Atal'Aman حمله کردند. حالا هم پر شده از این \"echoها...\"\nدست‌کم این‌طور است که Doru صدایشان می‌زند: echo. من فقط می‌بینم ارواحِ یک دورهٔ خونین‌تر. و مثل آن روزها، هر چقدر هم بزنی، بی‌پایان به داخل سرازیر می‌شوند.\nبرو بیرون و خودت ببین. بقایای echoها را هم بیاور. Doru می‌خواهد بفهمد چیستند و چطور کار می‌کنند.", o = { "Raider Ash Remains" }, p = "مثل خوابی است که از آن بیدار نمی‌شوی.", c = "دیدی؟ یک اقیانوس بی‌پایان.\nشاید Doru از خاکسترها چیزی یاد بگیرد." }
WoWFQ[93433] = { t = "نیایشگاه، مهر و موم، تحویل", d = "نفرین بر echoها.\nنفرین بر Zul'jin، و Mor'duun، و آن مار Malacrass هم.\nفقط برای زنده‌ها دردسر تازه می‌سازند.\nگوش کن، hash'ura. باید به هر نیایشگاه در شهر آذوقه برسانی. غذا، آب، بانداژ و reagent بسته‌بندی کرده‌ایم تا مانع‌هایشان با قدرت کامل بمانند.\nاز وضعیتشان هم بپرس. هرچند در امنیت‌اند، احتمالاً همه‌شان حس می‌کنند در محاصره‌اند.", o = { "با Eagletender Rhyd صحبت شد", "با Elder Thak صحبت شد", "با Elder Vu'lona صحبت شد", "با Elder Shimarra صحبت شد" }, p = "وضعیتشان چه؟ مشکلی با مانع‌ها نیست؟", c = "مانع‌ها سر جایشان‌اند؟ خوب.\nحالا می‌توانیم روی حمله متمرکز شویم." }
WoWFQ[93435] = { t = "چهار آشوبگر", d = "دیده‌بان‌ها گزارش داده‌اند چند چهرهٔ خاص میان echoها دیده‌اند. وقتی اسم‌ها را شنیدم، خشم‌های قدیمی درم جوشید.\nآن‌ها مبارزانی شریف نبودند که مثل تو با آن‌ها روبه‌رو شویم. کرم بودند--فرصت‌طلب‌های حریص که لشکری از ماجراجویان را به تحریک وام داشتند تا دارایی‌ها، گنج‌هایمان و... عاج‌هایمان را بدزدند.\nکشتن echoهای این چهره‌های کلیدی باید تعداد echoهایی که ظاهر می‌شوند را کم کند.\nو من هم لبخند می‌زنم وقتی بدانم افتاده‌اند.", o = { "Prigmon کشته‌شده", "Zungam کشته‌شده", "Budd Nedreck کشته‌شده", "Harrison Jones کشته‌شده" }, p = "باورت می‌شود این آشوبگرها سال‌ها بعد، وقتی Zandalari عروسک‌خودشان را بر سر کار گذاشت، برگشتند؟\n\"جاودان\" هم بودند دیگر، به‌ع...", c = "اعتراف می‌کنم، <name>: می‌دانم که کشتن آشوبگرها به استخوان‌های پیرم گرما داد.\nاین نظرت را از من عوض می‌کند؟" }
WoWFQ[93436] = { t = "افسون بر بی‌گناهان، اختلال بر گناهکاران", d = "خاکسترهایی که آوردی را بررسی می‌کنم، اما می‌توانیم بدون تبر هم این وضعیت را کنترل کنیم.\nباید میدان نبرد را به هم بریزی، hash'ura. echoها فکر می‌کنند در میانهٔ نبردی ده‌ها سال پیش هستند، پس باید به پشتیبانی‌ای که آن روزها داشتند ضربه بزنیم.\nسفره‌هایی را که برای استراحت می‌روند زهرآلود کن، متحدان غیرنظامی بی‌احترامشان را افسون کن، و آن صندوقی را که حریصانه غارتش می‌کنند خراب کن!", o = { "سفره‌ها زهرآلود شد", "غیرنظامیان افسون شدند", "Warlord's Chest خرابکاری شد", "Amani Hex Stave" }, p = "ثابت کنیم حتی echoهای گذشته هم می‌توانند اندوه را حس کنند.", c = "به‌خاطر کار تو، echoها مثل خوک‌های ترسیده از میدان نبرد در حال فرارند!" }
WoWFQ[93437] = { t = "در خونِ خودشان", d = "بعد از بررسی خاکسترها، Doru به این نتیجه رسید که تنها راه جنگیدن با گذشته، استفاده از سلاح‌های گذشته است.\nنمی‌توانم این را از هیچ Amani بخواهم. یا Witherbark، Revantusk، یا Shadowpine. حضورت با ما در این روزها باید تقدیر باشد... چون این درخواست را فقط از یک خارجی می‌توانیم بکنیم.\nباید در روح یکی از همان‌های ناپاک حلول شوی--کسانی که پیمان پلید Malacrass را پذیرفتند و در دوران Zul'jin از قدرت loa تغذیه کردند.\nبه نیایشگاه همان ناپاکی که می‌خواهی با او یکی شوی برگرد.\nنیاکان ما را ببخشند...", o = { "در Avatarِ loa حلول کن", "Echoها کشته‌شده", "با قابلیت Time Flies سفر کن", "Raid Leader کشته‌شده" }, p = "سپاسگزاریم که Akil'zon چشم‌هایمان را به حقیقت کارهای تاریک Zul'jin و Malacrass باز کرد.\nحتی اگر معنایش این باشد که شرمشان را به‌عنوان شرم خودمان بپذیریم.", c = "ممنونم، hash'ura. از صمیم قلب.\nنبرد با echoها ادامه دارد. اما به‌نظر می‌رسد حالا که رهبرشان حساب شد، echoها بعد از کشته شدن دیگر برنمی‌گردند.\nاین چند روز خاطرات خونم را به جوش آورد. حالا می‌توانیم همه استراحت کنیم. شاید حتی رها کنیم و برویم؟\nبه‌ع! این‌ها فقط یاوه‌های یک جنگجوی پیر است. حواست نیست.\nفقط بدان که در قسمت توام." }
WoWFQ[93440] = { t = "تاریخچهٔ شخصی", d = "با کشته شدن Mor'duun و شکست Twilight's Blade، قومم می‌خواهد به Atal'Aman برگردد.\nباید لحظه‌ای برای جشن بزرگ باشد اما... چیز پیش‌بینی‌نشده‌ای سر راهمان است.\nبرو سراغ Torundo و Elder Doru. آن‌ها بازسازی را پیش می‌برند. بهترین می‌دانند استعدادهای تو را کجا خرج کنند.\nآماده شو، hash'ura، و در دفاع از Atal'Aman، هر کس که آن‌جا دیدی، تردید نکن.", c = "Zul'jarra فرستاده، hash'ura؟\nخوش. معلوم است از انتظار کشیدن برای پیشرفت ما خسته شده." }
WoWFQ[93575] = { t = "غارهای Maisara: گرسنگی Maisara", d = "قومم را نمی‌گذارم برای آیین‌های تاریک Vilebranchها بمیرند. باید دنبالشان برویم.\nقلب Maisara Caverns جایی است که Vilebranchها رازهایشان را نگه می‌دارند. انتظار یک سفر خونین را دارم. باید با زشتی حریصانهٔ Vilebranchها روبه‌رو شویم و ببینیم این حریصی برای همه‌مان چه هزینه‌ای دارد.\nباید بفهمیم برای خویشاوندان ربوده‌شده‌ام چه نقشه‌ای دارند؛ اگر کسی هنوز زنده باشد. خودم هم می‌آیم کمکت کنم... اما یک گروه جنگی سرسخت بیاور. لازمش خواهیم داشت.", o = { "Vordaza کشته‌شده", "Rak'tul کشته‌شده" }, p = "گروه جنگی‌ات را جمع کن. در Maisara Caverns می‌بینمت.", c = "این حسابی کار تاریکی بود. این‌همه آدم، به سرنوشتی این‌قدر هولناک!\nاما دیگر نه، به لطف تو. Witherbarkها و من، هر دو، از تو ممنونیم." }
WoWFQ[93667] = { t = "اردوگاه Stonewash", d = "اولین چیز عجیبی نیستی که امروز دیدم.\n<Scout Zel'kanra shakes her head.>\nدر مسیر Jan'Alor یک موجود بزرگ پوستی دیدم. Amaxi چند دیده‌بان برداشت و دنبالش رفت.\nمدتی است که خبری نیست. حوصله داری بروی حالشان را بپرسی؟", c = "تو کی هستی؟ این‌جا چه کار می‌کنی؟\n<Amaxi tenses, but relaxes after a moment.>\nShadebasin فرستاده. آره، حالمان خوب است. اما این tortollanها نباید این‌جا باشند!" }
WoWFQ[93734] = { t = "گنج‌های کوچک", d = "بالاخره می‌فهمیم Groffa چه گنج‌هایی را انبار کرده بود!\n<Furgh's eyes go black as he looks at the bag. The drool on his jowls turns to foam and his claws dig into the sides of the bag as his grip on it tightens.>\nشاید هدیه‌های گویندهٔ loa آن‌قدرهای هم بد نباشد. نباید عجله کنیم. خودم نگاه می‌کنم. تو تماشا کن و از من محافظت کن.", o = { "به‌دقت Furgh را زیر نظر بگیر", "گنج Groffa را بسوزان" }, p = "هر چه Groffa داشت بد بود. نه؟", c = "لازم نبود وسایلم را بسوزانی..." }
WoWFQ[93792] = { t = "برکت‌های loa", d = "اسم من Du'gal است. و تو hash'ura هستی.\nKinduru دستور داده راه‌های پرستش loa را به تو یاد بدهم. به این افتخار کن. خیلی کم از gokinyeها چنین حقی به دست آورده‌اند.\nکنار من، Altar of Blessings است. می‌توانی از آن برای پرستش هر یک از loaهایمان استفاده کنی و در پاسخ، ذره‌ای قدرت می‌گیری.\nخب، بفرما، لطفاً.", o = { "از Altar of Blessings استفاده کن" }, p = "loaها واقعاً سخاوتمندند.", c = "روحت از قدرت سرشار است!\nهر وقت خواستی می‌توانی از محراب استفاده کنی. اما در هر لحظه فقط می‌توانی یک برکت داشته باشی." }
WoWFQ[94528] = { t = "جا باز کردن", d = "بعد از آن‌چه گذشت، کمی وقت می‌خواهم. حس می‌کنم بدنم با خودش می‌جنگد.\nاما در سرزمین دشمن هستیم. نمی‌گذارم فقط به‌خاطر... به‌خاطر این‌که ناچار شدم به دنبالش بپرم، به دست دشمن بیفتیم. باید Umbric را در امنیت نگه داریم.\nمی‌شود Twilight's Bladeهای دور و برمان را پاک کنی تا جایی برای نفس کشیدن باز شود؟", o = { "Twilight's Blade کشته‌شده" }, p = "انگار نیمه‌ای از من با نیمهٔ دیگر در حال جنگ است.", c = "ممنونم. فکر کنم حالا روی حواسم هست.\nعجیب است. Antenorian مرا فرزند Light می‌نامید و با این حال...\n<Arator looks at his hands, pondering.>" }
WoWFQ[94529] = { t = "سایه‌ای تاریک کمین کرده", d = "شانس آوردیم که از آن پارگی در Void جان سالم به در بردیم، اما حالا فرصتی پیش روی ماست.\nAntenorian حتماً به این سمت می‌رفت، به همین دلیل است که دیگر در Eversong نیستیم. اما سفرش را قطع کردیم و هنوز همین‌جاست.\nمثل سوزنی در پشت گردنم حسش می‌کنم.\nببین می‌توانی اطلاعات بیشتری از Twilight's Bladeهای این‌جا دربیاوری. آن دروازه‌ای که Antenorian از آن گفت چه؟ آن پیشگویی‌های Amani چه؟", o = { "کمی بمان و گوش کن", "Twilight Correspondence پیدا شد" }, p = "چیز دیگری از نقشه‌های Twilight's Blade پیدا نکردی؟", c = "پس Xal'atath از Darkwell دروازه‌ای باز کرده و Twilight's Blade منتظر رسیدن یک Dark General هستند.\nاز کجا می‌دانند دارد می‌آید؟ و کجا ظاهر می‌شود؟\nاین ماجرا هر لحظه پیچیده‌تر و هولناک‌تر می‌شود." }
WoWFQ[94530] = { t = "ندای خلا", d = "توانستم رد Antenorian را دنبال کنم. بعد از آن سرک کشیدن به فضای Void، قوی‌تر از قبل شده.\nخوش‌شانسی که همین باعث می‌شود ردش را راحت بگیرم. زیر پای ماست، در حفره‌ای باز زیر زمین. می‌توانم آن‌جا دروازه‌ای باز کنم.\n<Umbric glances over at Arator.>\nامیدوارم بتوانیم به این ماجرا پایان دهیم و Arator هم آسیبی ندیده باشد. وقتی شروع کردیم، فکر می‌کردم چند طومار پیدا می‌کنیم، نقشه‌شان را درمی‌آوریم و خودمان جلویش را می‌گیریم.\nاین را پیش‌بینی نکرده بودم.", o = { "ورود به Umbric's Portal", "Lord Antenorian شکست‌خورده", "برای خروج از Tomb of Mun'jin از دروازه استفاده کن" }, c = "همه‌اش یک تله بود. مرگ Ula'tek فقط چیز بدتری آزاد می‌کند.\nTwilight's Blade این را می‌دانست. و ما کور بودیم.\nمن کور بودم." }
WoWFQ[94635] = { t = "ژست بگیر", d = "Trial of Style به ما این فرصت را می‌دهد که خوش‌تیپ به نظر برسیم، <class>.\nدوربین مطمئن می‌شود خوش‌تیپ بمانیم.\nپس به من و دوربینم تمرکز کن، حرف‌هایم را اجرا کن و من مطمئن می‌شوم فوق‌العاده به نظر برسی!", o = { "روی عکاس تمرکز کن و از او پیروی کن." }, p = "به من تمرکز کن و از حرف‌هایم پیروی کن.\nمطمئنت می‌کنم عالی به نظر برسی.", c = "دوربین دروغ نمی‌گوید، <name>.\nتو یک <class> خیلی خوش‌استایل هستی." }
WoWFQ[94636] = { t = "ژست بگیر", o = { "روی عکاس تمرکز کن و از او پیروی کن." } }
WoWFQ[94867] = { t = "گم‌شده در Atal'Abasi", d = "Tolbani و Jehnira مدتی است ناپدید شده‌اند. آخرین خبر، داشتند برای آذوقه از Atal'Abasi دیده‌بانی می‌کردند.\nآن ناحیه پر از murloc است. تعداد زیادشان برای یک Amani هم خطرناک است.\nپیدایشان کن و مطمئن شو حالشان خوب است!", c = "Vakala تو را فرستاده؟ حق داشت که فکر کند این‌جا خطرناک است." }
WoWFQ[94868] = { t = "این کار دو نفر می‌خواهد", d = "Jan'alai یک مادر است! و این یعنی تخم!\nتخم‌های loa بی‌قرارند! باید با احتیاط از تخم دربیایند. خانواده‌ام نسل‌ها این افتخار را داشته‌اند، اما سنت وقتی از بین رفت که برادران بزرگ‌ترم به وعده‌های دروغین Zul'jin دل خوش کردند. افسوس، من تنها برادر باقی‌مانده‌ام و برای این آیین دو جوجه‌کش لازم است!\nبرادرزاده‌ام، Shaja، را پای ساحل پیدا کن. او برای دانستن این آیین خیلی کوچک است، اما برکت loa مثل برادرانم در رگ‌های او هم جاری است. وقتش رسیده این افتخار را بشناسد.", o = { "Shaja پیدا شد", "با Shaja صحبت کن", "Young Amazard پاک شد", "پیام Brek رسانده شد", "Shaja's Cleansing Vial", "در Temple of Jan'alai با Shaja صحبت کن." }, c = "راه برگشت خطرناک بود، اما سالم رسیدم.\nدارم برای عمویم از ماجرایمان می‌گویم. عاشق قصه‌های خوب است." }
WoWFQ[94869] = { t = "جوجه‌های گشنه", d = "به‌زودی به تخم‌ها برکت می‌رسد! Jan'alai این را به من گفته. و وقتی این تخم‌ها باز شوند، عدهٔ زیادی دهان گرسنه خواهیم داشت! آن‌ها چیزهایی نرم، لطیف و تندبو می‌خواهند.\n<Brek eyes you up and down.>\nبهتر است خودت را به ساحل برسانی و چیزی پیدا کنی که جوجه‌ها را اغوا کند، وگرنه ممکن است لقمه‌ای از تو بچینند!\n<Brek laughs.>", o = { "Pungent Crab Tomalley", "برگرد پیش Brek", "Pungent Crab Tomalley به دیگ آشپزی Amani در Temple of Jan'alai اضافه شد." }, p = "<It's going to take ages to get this smell out of your armor.>", c = "<Hopefully this will be enough food for the hatchlings.>" }
WoWFQ[94870] = { t = "محافظت اضافه، ضرری ندارد", d = "تخم‌ها تقریباً آماده‌اند!\n<Brek glances eagerly at both clutches of eggs.>\nتو شاید چیزهایی دربارهٔ این بدانی، نه؟ Jan'alai این را به من گفته. کمبود خونت را با روحت جبران می‌کنی. کمکم کن Shaja را آموزش بدهم! روح به‌تنهایی برای این آیین کافی نیست. تخم‌ها با قدرت خودِ loa پر شده‌اند و با انرژی آتشین خواهند ترکید!\nما می‌توانیم جلویش را از تو بگیریم، اما اول پر لازم داریم. پرهای loa! دور معبد جمعشان کن... مگر این‌که جرئت کنی خودت از خود loa بپرسی!", o = { "Feather of Jan'alai" }, p = "پرها را آوردی؟ یا قرار است ذوب شوی؟", c = "آها! پرها!\nاین‌ها در آیین از تو محافظت می‌کنند، اما اول باید کمی جادو رویت کنیم. وقتی تو سر و کله می‌زدی، برکت محافظت را به Shaja یاد دادم.\nنگران نباش! او استعداد ذاتی دارد.\n<Brek grins wildly.>" }
WoWFQ[94882] = { t = "وقت‌بندی بی‌نقص", d = "همه‌چیز آماده است! حالا هر دوتان را از آیین جوجه‌کشی عبور می‌دهم!\nبا Shaja حرف بزن؛ او با پرها تو را از آن انرژی‌های قدرتمند loa محافظت می‌کند.", o = { "پذیرش برکت محافظت Shaja", "به دستورالعمل‌های Loa Speaker Brek گوش کن", "کنار Loa Speaker Brek جای بگیر", "صبر کن Shaja سر جایش بایستد", "Eggs of Jan'alai از تخم درآمدند" }, p = "عجله! تخم‌ها آماده‌اند بترکنند!", c = "جوجه‌کشی تمام شد! امیدوارم اولین از تخم‌های آیندهٔ بسیار باشد. Jan'alai را ستایش باد!\nمن و Shaja این میراث را ادامه می‌دهیم و به جوجه‌های تازهٔ بسیاری در سرزمینمان خوش‌آمد می‌گوییم." }
WoWFQ[94883] = { t = "مثل dragonhawk به سوی شعله", d = "می‌دانم عمویم گاهی به‌نظر... عجیب می‌آید. حرف‌هایش دربارهٔ loa برای من همیشه مثل قصه‌های بچگی بود.\nاما از وقتی Jan'alai برگشته، من هم انرژی‌اش را حس می‌کنم! او سوسو می‌زند، دود می‌کند، سرخ‌داغ می‌سوزد. گرما، روشنایی و زندگی هم می‌آورد!\nاما چیزی که الان از او حس می‌کنم پریشانی است--پریشانی مادرخروسی که بچه‌هایش را می‌شمارد و یکی کم می‌آورد.\nبرویم سراغ جوجه‌ها. اگر دوتکه شویم، سریع‌تر همه‌جا را می‌گردیم.", o = { "حال یک جوجه را چک کن", "حال جوجهٔ دوم را چک کن", "حال جوجهٔ سوم را چک کن", "Cinderscale Patriarch کشته‌شده" }, c = "ممنونم، <name>. و Jan'alai هم از تو ممنون است.\nمی‌دانم این راه من است. با خون و با قلب خودم. شاید هرگز مثل مادرم به میدان نروم، اما او می‌فهمد که من به شیوهٔ خودم به Amaniها--و Jan'alai--خدمت می‌کنم." }
WoWFQ[95199] = { t = "اتحاد لرزان", d = "پنج دقیقه که کنار هم بودیم، گروه قهرمانانمان همین الان روی خودش فرو می‌ریزد.\nاین‌طور به جایی نمی‌رسیم. لازم نیست همدیگر را دوست داشته باشیم، اما اگر می‌خواهیم هیولایی مثل Kith'ix را سرنگون کنیم، باید هم‌سو باشیم.\nحواست به بقیه باشد. ببین می‌توانی عقل‌ها را حاکم کنی.", o = { "قایق‌ها آماده شد", "پاروها جمع شد", "آذوقه پس گرفته شد", "سلاح‌ها یافت شد" }, c = "آدم را خجل می‌کند که اگر این چند ماه در Zul'Aman کار نکرده بودیم، من هم مثل بقیه از این ماجرا خشمگین می‌شدم.\nاما همین حالا مهم نیست. تنها چیزی که مهم است بقای هر دو ملت ماست." }
WoWFQ[95200] = { t = "پیشکشی برای Halazzi", d = "اگر توی آب لو برویم، هرگز از آن صخره‌های Atal'Utek بالا نمی‌رویم. باید سریع و بی‌صدا نزدیک شویم.\nبرکتی از Halazzi در این کار کمک می‌کند. اما خوب می‌دانی که Halazzi برکت را مجانی نمی‌دهد.\nبرو شکار. پیشکشی مناسب loa سیاه‌گوش پیدا کن و تقدیمش کن.", o = { "Fresh Beast Heart", "پیشکش تقدیم شد" }, p = "توی آب‌ها مواظب باش، hash'ura. شانس‌مان همین‌طور هم کم است، نباید غذای thresher شوی.", c = "از سفر به معبد loa سیاه‌گوش تا حالا مه این‌قدر غلیظ ندیده بودم. به‌نظر می‌رسد Halazzi پیشکش تو را پسندید." }
WoWFQ[96388] = { t = "پیوستن به Abyss Anglers", d = "تا حالا اسم Abyss Anglers را شنیده‌ای؟\nقبیله‌های جنگل نسل‌هاست هم از خشکی شکار می‌کنند هم از آب.\nشرم نداشته باش، hash'ura. یک لباس بردار و شیرجه بزن!", o = { "با Depthdiver Jeju صحبت کن تا شیرجه آغاز شود", "با Harpoon ماهی صید شد", "Sunken Relic جمع شد", "برای پایان شیرجه از قابلیت \"Surface!\" استفاده شد" }, p = "لباس خوب نشست؟", c = "تو یک شیرجه‌رو ذاتی هستی، hash'ura!\nچند Angler Pearl هم بگیر. به‌اندازهٔ کافی جمع کن و به من یا Tu'nakit برگردان تا ثابت کنی برای تجهیزات بهتر آماده‌ای!" }
